static void byte_buffer_move(makocode::ByteBuffer& dest, makocode::ByteBuffer& src) {
    dest.release();
    dest.data = src.data;
    dest.size = src.size;
    dest.capacity = src.capacity;
    src.data = 0;
    src.size = 0;
    src.capacity = 0;
}

