static bool title_char_is_allowed(char c) {
    bool is_digit = (c >= '0' && c <= '9');
    bool is_upper = (c >= 'A' && c <= 'Z');
    bool is_lower = (c >= 'a' && c <= 'z');
    if (is_digit || is_upper || is_lower) {
        return true;
    }
    switch (c) {
        case ' ':
        case '!':
        case '@':
        case '#':
        case '$':
        case '%':
        case '^':
        case '&':
        case '*':
        case '+':
        case '(':
        case ')':
        case '{':
        case '}':
        case '[':
        case ']':
        case ':':
        case '"':
        case ';':
        case '\'':
        case '<':
        case '=':
        case '>':
        case '?':
        case ',':
        case '-':
        case '.':
        case '/':
        case '`':
        case '~':
        case '|':
        case '\\':
        case '_':
            return true;
        default:
            break;
    }
    return false;
}

static usize decimal_digit_count(u64 value) {
    usize digits = 0u;
    while (value) {
        value /= 10u;
        ++digits;
    }
    return digits ? digits : 1u;
}

static usize footer_compute_page_text_length(const PageFooterConfig& footer,
                                             u64 page_index,
                                             u64 page_count) {
    usize length = 0u;
    bool need_separator = false;
    if (footer.has_title && footer.title_text && footer.title_length) {
        length += footer.title_length;
        need_separator = true;
    }
    if (footer.display_filename && footer.has_filename && footer.filename_text && footer.filename_length) {
        if (need_separator) {
            length += 3u; // " | "
        }
        length += footer.filename_length;
        need_separator = true;
    }
    if (footer.display_page_info) {
        if (need_separator) {
            length += 3u; // " | "
        }
        length += 5u; // "Page "
        length += decimal_digit_count(page_index);
        length += 1u; // '/'
        length += decimal_digit_count(page_count);
    }
    return length;
}

static usize footer_compute_max_text_length(const PageFooterConfig& footer,
                                            u64 page_count) {
    usize max_length = 0u;
    for (u64 index = 1u; index <= page_count; ++index) {
        usize length = footer_compute_page_text_length(footer, index, page_count);
        if (length > max_length) {
            max_length = length;
        }
    }
    return max_length;
}

static bool footer_build_page_text(const PageFooterConfig& footer,
                                   u64 page_index,
                                   u64 page_count,
                                   makocode::ByteBuffer& buffer) {
    usize length = footer_compute_page_text_length(footer, page_index, page_count);
    if (!buffer.ensure(length + 1u)) {
        return false;
    }
    usize cursor = 0u;
    bool need_separator = false;
    if (footer.has_title && footer.title_text && footer.title_length) {
        for (usize i = 0u; i < footer.title_length; ++i) {
            buffer.data[cursor++] = (u8)footer.title_text[i];
        }
        need_separator = true;
    }
    if (footer.display_filename && footer.has_filename && footer.filename_text && footer.filename_length) {
        if (need_separator) {
            buffer.data[cursor++] = ' ';
            buffer.data[cursor++] = '|';
            buffer.data[cursor++] = ' ';
        }
        for (usize i = 0u; i < footer.filename_length; ++i) {
            buffer.data[cursor++] = (u8)footer.filename_text[i];
        }
        need_separator = true;
    }
    if (footer.display_page_info) {
        if (need_separator) {
            buffer.data[cursor++] = ' ';
            buffer.data[cursor++] = '|';
            buffer.data[cursor++] = ' ';
        }
        buffer.data[cursor++] = 'P';
        buffer.data[cursor++] = 'a';
        buffer.data[cursor++] = 'g';
        buffer.data[cursor++] = 'e';
        buffer.data[cursor++] = ' ';
        char number[32];
        u64_to_ascii(page_index, number, sizeof(number));
        usize digits = 0u;
        while (number[digits]) {
            buffer.data[cursor++] = (u8)number[digits++];
        }
        buffer.data[cursor++] = '/';
        u64_to_ascii(page_count, number, sizeof(number));
        digits = 0u;
        while (number[digits]) {
            buffer.data[cursor++] = (u8)number[digits++];
        }
    }
    buffer.data[length] = 0u;
    buffer.size = length;
    return true;
}

static bool compute_page_layout(const ImageMappingConfig& mapping,
                                PageFooterConfig& footer_config,
                                u64 frame_bit_count,
                                u32 width_pixels,
                                u32 height_pixels,
                                FooterLayout& footer_layout,
                                u32& data_height_pixels,
                                u64& bits_per_page,
                                u64& page_count) {
    data_height_pixels = height_pixels;
    bits_per_page = 0u;
    page_count = 1u;
    const u32 MAX_FOOTER_LAYOUT_PASSES = 16u;
    bool layout_converged = false;
    for (u32 pass = 0u; pass < MAX_FOOTER_LAYOUT_PASSES; ++pass) {
        u64 text_page_count = footer_config.display_page_info ? page_count : 1u;
        footer_config.max_text_length = footer_compute_max_text_length(footer_config, text_page_count);
        if (!compute_footer_layout(width_pixels, height_pixels, footer_config, footer_layout)) {
            return false;
        }
        data_height_pixels = footer_layout.data_height_pixels;
        if (!compute_bits_per_page(mapping,
                                   width_pixels,
                                   height_pixels,
                                   data_height_pixels,
                                   bits_per_page)) {
            return false;
        }
        u64 new_page_count = (frame_bit_count + bits_per_page - 1u) / bits_per_page;
        if (new_page_count == 0u) {
            new_page_count = 1u;
        }
        if (!footer_config.display_page_info || new_page_count == page_count) {
            page_count = new_page_count;
            layout_converged = true;
            break;
        }
        page_count = new_page_count;
    }
    return layout_converged;
}

static bool validate_overwrite_budget(const ImageMappingConfig& mapping,
                                           const makocode::ByteBuffer& frame_bits,
                                           u64 frame_bit_count,
                                           u32 width_pixels,
                                           u32 height_pixels,
                                           u32 data_height_pixels,
                                           u64 bits_per_page,
                                           u64 page_count,
                                           const makocode::EccSummary& ecc_summary,
                                           u16 unknown_parity_budget,
                                           u16 overlay_erasure_budget,
                                           u16* minimum_parity_required_out = 0) {
    if (minimum_parity_required_out) *minimum_parity_required_out = 0u;
    if (mapping_has_custom_palette(mapping) &&
        !is_power_of_two_u32(mapping.custom_palette_count)) {
        u64 expected_bits_per_page = 0u;
        return compute_bits_per_page(mapping,
                                     width_pixels,
                                     height_pixels,
                                     data_height_pixels,
                                     expected_bits_per_page) &&
               expected_bits_per_page == bits_per_page;
    }
    if (!ecc_summary.enabled || !ecc_summary.block_data_symbols ||
        !ecc_summary.parity_symbols || !ecc_summary.block_count ||
        frame_bit_count == 0u || !frame_bits.data ||
        ecc_summary.block_count > 0xFFFFFFFFu) {
        return false;
    }
    double bits_per_pixel_value = mapping_bits_per_data_pixel(mapping);
    if (bits_per_pixel_value < 1.0 || bits_per_pixel_value > 24.0) return false;
    u32 bits_per_pixel = (u32)bits_per_pixel_value;
    if ((double)bits_per_pixel != bits_per_pixel_value) return false;
    u64 expected_bits_per_page = 0u;
    if (!compute_bits_per_page(mapping,
                               width_pixels,
                               height_pixels,
                               data_height_pixels,
                               expected_bits_per_page)) {
        return false;
    }
    if (expected_bits_per_page != bits_per_page) return false;
    u64 frame_bytes_u64 = (frame_bit_count + 7u) >> 3u;
    if (frame_bytes_u64 == 0u || frame_bytes_u64 > (u64)USIZE_MAX_VALUE) return false;
    makocode::ByteBuffer erased_frame_bits;
    if (!erased_frame_bits.ensure((usize)frame_bytes_u64)) return false;
    erased_frame_bits.size = (usize)frame_bytes_u64;
    for (usize i = 0u; i < erased_frame_bits.size; ++i) erased_frame_bits.data[i] = 0u;
    for (u64 page = 0u; page < page_count; ++page) {
        if (page && bits_per_page > U64_MAX_VALUE / page) return false;
        u64 page_bit_offset = page * bits_per_page;
        if (page_bit_offset >= frame_bit_count) break;
        u64 segment_bits = frame_bit_count - page_bit_offset;
        if (segment_bits > bits_per_page) segment_bits = bits_per_page;
        CenteredDataRectangle payload_rectangle;
        u64 payload_pixels = segment_bits / bits_per_pixel;
        if (segment_bits % bits_per_pixel) ++payload_pixels;
        if (!compute_centered_data_rectangle(width_pixels,
                                             data_height_pixels,
                                             payload_pixels,
                                             payload_rectangle)) {
            return false;
        }
        makocode::ByteBuffer overwrite_mask;
        if (!compute_page_payload_overwrite_mask(mapping,
                                                 width_pixels,
                                                 height_pixels,
                                                 data_height_pixels,
                                                 frame_bit_count,
                                                 page + 1u,
                                                 page_count,
                                                 &ecc_summary,
                                                 unknown_parity_budget,
                                                 overlay_erasure_budget,
                                                 overwrite_mask)) {
            return false;
        }
        u64 payload_bit_cursor = 0u;
        for (u32 y = payload_rectangle.y0;
             y < payload_rectangle.y0 + payload_rectangle.height;
             ++y) {
            for (u32 x = payload_rectangle.x0;
                 x < payload_rectangle.x0 + payload_rectangle.width;
                 ++x) {
                u32 pixel_bits = bits_per_pixel;
                u64 local_slot = payload_bit_cursor;
                payload_bit_cursor += pixel_bits;
                usize pixel_index = (usize)y * (usize)width_pixels + (usize)x;
                if (pixel_index >= overwrite_mask.size ||
                    overwrite_mask.data[pixel_index] != OVERWRITE_MASK_PIXEL) continue;
                for (u32 bit = 0u; bit < pixel_bits; ++bit) {
                    u64 bit_slot = local_slot + bit;
                    if (bit_slot >= segment_bits) continue;
                    u64 bit_index = page_bit_offset + bit_slot;
                    if (bit_index >= frame_bit_count) continue;
                    usize byte_index = (usize)(bit_index >> 3u);
                    u8 bit_mask = (u8)(1u << (bit_index & 7u));
                    erased_frame_bits.data[byte_index] |= bit_mask;
                }
            }
        }
    }
    u64 payload_bit_count = frame_bit_count;
    u64 payload_byte_count_u64 = (payload_bit_count + 7u) >> 3u;
    if (payload_byte_count_u64 > (u64)USIZE_MAX_VALUE) return false;
    usize payload_byte_count = (usize)payload_byte_count_u64;
    makocode::ByteBuffer erased_payload;
    if (!erased_payload.ensure(payload_byte_count)) return false;
    erased_payload.size = payload_byte_count;
    for (usize byte_index = 0u; byte_index < payload_byte_count; ++byte_index) {
        bool erased = false;
        u64 first_frame_bit = (u64)byte_index * 8u;
        u64 end_frame_bit = first_frame_bit + 8u;
        if (end_frame_bit > frame_bit_count) end_frame_bit = frame_bit_count;
        for (u64 bit_index = first_frame_bit; bit_index < end_frame_bit; ++bit_index) {
            if (erased_frame_bits.data[bit_index >> 3u] & (u8)(1u << (bit_index & 7u))) {
                erased = true;
                break;
            }
        }
        erased_payload.data[byte_index] = erased ? 1u : 0u;
    }
    u64 header_span_u64 = 0u;
    u64 block_total = (u64)ecc_summary.block_data_symbols + ecc_summary.parity_symbols;
    if (header_span_u64 > payload_byte_count ||
        block_total > U64_MAX_VALUE / ecc_summary.block_count ||
        header_span_u64 + block_total * ecc_summary.block_count > payload_byte_count) {
        return false;
    }
    usize header_span = (usize)header_span_u64;
    if (payload_byte_count > header_span &&
        !makocode::fisher_yates_unshuffle(erased_payload.data + header_span,
                                          payload_byte_count - header_span)) {
        return false;
    }
    u32 maximum_required_parity = 0u;
    for (u64 block = 0u; block < ecc_summary.block_count; ++block) {
        u64 block_offset = header_span_u64 + block * block_total;
        u32 structural_erasures = 0u;
        for (u64 symbol = 0u; symbol < block_total; ++symbol) {
            if (erased_payload.data[(usize)(block_offset + symbol)]) ++structural_erasures;
        }
        u32 required_parity = structural_erasures +
                              (u32)unknown_parity_budget +
                              (u32)overlay_erasure_budget;
        if (required_parity > maximum_required_parity) {
            maximum_required_parity = required_parity;
        }
    }
    if (minimum_parity_required_out) {
        *minimum_parity_required_out = (maximum_required_parity > 0xFFFFu)
                                          ? 0xFFFFu
                                          : (u16)maximum_required_parity;
    }
    return maximum_required_parity <= ecc_summary.parity_symbols;
}

static bool derive_ecc_redundancy_with_overwrite(usize payload_bytes,
                                          double requested_redundancy,
                                          double structural_fraction,
                                          double& effective_redundancy,
                                          u16& unknown_parity_budget,
                                          u16& overlay_erasure_budget,
                                          bool reserve_overlay) {
    effective_redundancy = 0.0;
    unknown_parity_budget = 0u;
    overlay_erasure_budget = 0u;
    (void)structural_fraction;
    if (requested_redundancy < 0.0 || payload_bytes == 0u) return false;
    u16 block_data = 0u;
    u16 block_parity = 0u;
    u64 block_count = 0u;
    if (!makocode::compute_ecc_layout(payload_bytes,
                                      requested_redundancy,
                                      block_data,
                                      block_parity,
                                      block_count) ||
        !block_data || !block_parity || !block_count) {
        return false;
    }
    u16 overlay = (requested_redundancy > 0.0 && reserve_overlay)
                      ? (u16)(block_parity / 2u)
                      : 0u;
    u16 unknown = (u16)(2u * ((u32)block_parity / 2u));
    if (requested_redundancy > 0.0 && unknown < 32u) {
        unknown = 32u;
    }
    double encoded_redundancy = requested_redundancy;
    u32 required_parity = (u32)unknown + (u32)overlay;
    if (required_parity > block_parity) {
        encoded_redundancy = payload_bytes < makocode::RS_FIELD_SIZE &&
                                     required_parity <= makocode::RS_FIELD_SIZE - payload_bytes
                                 ? (double)required_parity / (double)payload_bytes
                                 : ((double)required_parity - 0.5) /
                                       ((double)makocode::RS_FIELD_SIZE -
                                        (double)required_parity);
        u16 adjusted_data = 0u;
        u16 adjusted_parity = 0u;
        u64 adjusted_blocks = 0u;
        if (!makocode::compute_ecc_layout(payload_bytes,
                                          encoded_redundancy,
                                          adjusted_data,
                                          adjusted_parity,
                                          adjusted_blocks) ||
            !adjusted_data || !adjusted_blocks || adjusted_parity < required_parity) {
            return false;
        }
    }
    unknown_parity_budget = unknown;
    overlay_erasure_budget = overlay;
    effective_redundancy = requested_redundancy > 0.0
                               ? encoded_redundancy
                               : (double)block_parity / (double)block_data;
    return true;
}

static bool compute_frame_statistics(usize payload_bytes,
                                     double redundancy,
                                     u16& block_data,
                                     u16& parity_symbols,
                                     u64& block_count,
                                     u64& payload_bit_count,
                                     u64& frame_bit_count) {
    block_data = 0u;
    parity_symbols = 0u;
    block_count = 0u;
    payload_bit_count = 0u;
    frame_bit_count = 0u;
    if (payload_bytes == 0u) {
        return true;
    }
    if (redundancy <= 0.0) {
        return false;
    }
    if (!makocode::compute_ecc_layout(payload_bytes, redundancy, block_data, parity_symbols, block_count)) {
        return false;
    }
    if (block_data == 0u || parity_symbols == 0u || block_count == 0u) {
        return false;
    }
    u64 total_symbols = (u64)(block_data + parity_symbols) * block_count;
    if (total_symbols > (U64_MAX_VALUE / 8u)) {
        return false;
    }
    u64 encoded_bits = total_symbols * 8u;
    payload_bit_count = encoded_bits;
    frame_bit_count = encoded_bits;
    return true;
}

struct EccFillCandidate {
    double ratio;
    double requested_ratio;
    u16 block_data;
    u16 parity;
    u64 block_count;
    u64 payload_bits;
    u64 frame_bits;
    u64 bits_per_page;
    u64 page_count;
};

static bool evaluate_ecc_fill_candidate(usize payload_bytes,
                                        double requested_redundancy,
                                        const ImageMappingConfig& mapping,
                                        const PageFooterConfig& footer_template,
                                        u32 width_pixels,
                                        u32 height_pixels,
                                        double structural_erasure_fraction,
                                        bool reserve_overlay,
                                        EccFillCandidate& candidate) {
    double encoded_redundancy = requested_redundancy;
    u16 unknown_budget = 0u;
    u16 overlay_budget = 0u;
    if (!derive_ecc_redundancy_with_overwrite(payload_bytes,
                                              requested_redundancy,
                                              structural_erasure_fraction,
                                              encoded_redundancy,
                                              unknown_budget,
                                              overlay_budget,
                                              reserve_overlay)) {
        return false;
    }

    FooterLayout layout = FooterLayout();
    u32 layout_data_height = height_pixels;
    u64 bits_per_page = 0u;
    u64 page_count = 0u;
    bool exact_budget_valid = false;
    makocode::ByteBuffer dummy_frame;
    if (!dummy_frame.ensure(1u)) return false;
    dummy_frame.size = 1u;

    for (u32 parity_attempt = 0u;
         parity_attempt < makocode::RS_FIELD_SIZE;
         ++parity_attempt) {
        if (!compute_frame_statistics(payload_bytes,
                                      encoded_redundancy,
                                      candidate.block_data,
                                      candidate.parity,
                                      candidate.block_count,
                                      candidate.payload_bits,
                                      candidate.frame_bits) ||
            candidate.block_data == 0u || candidate.parity == 0u) {
            return false;
        }
        PageFooterConfig footer_copy = footer_template;
        if (!compute_page_layout(mapping,
                                 footer_copy,
                                 candidate.frame_bits,
                                 width_pixels,
                                 height_pixels,
                                 layout,
                                 layout_data_height,
                                 bits_per_page,
                                 page_count)) {
            return false;
        }
        makocode::EccSummary summary;
        summary.enabled = true;
        summary.block_data_symbols = candidate.block_data;
        summary.parity_symbols = candidate.parity;
        summary.redundancy = encoded_redundancy;
        summary.original_bytes = payload_bytes;
        summary.block_count = candidate.block_count;
        u16 required_parity = 0u;
        if (validate_overwrite_budget(mapping,
                                      dummy_frame,
                                      candidate.frame_bits,
                                      width_pixels,
                                      height_pixels,
                                      layout_data_height,
                                      bits_per_page,
                                      page_count,
                                      summary,
                                      unknown_budget,
                                      overlay_budget,
                                      &required_parity)) {
            exact_budget_valid = true;
            break;
        }
        if (!required_parity || required_parity >= makocode::RS_FIELD_SIZE - 1u) {
            return false;
        }
        u16 target_parity = (u16)(required_parity + 1u);
        if (target_parity <= candidate.parity) return false;
        double retry_redundancy = payload_bytes < makocode::RS_FIELD_SIZE &&
                                          target_parity <=
                                              (u64)makocode::RS_FIELD_SIZE - payload_bytes
                                      ? (double)target_parity / (double)payload_bytes
                                      : ((double)target_parity - 0.5) /
                                            ((double)makocode::RS_FIELD_SIZE -
                                             (double)target_parity);
        u16 retry_data = 0u;
        u16 retry_parity = 0u;
        u64 retry_blocks = 0u;
        if (!makocode::compute_ecc_layout(payload_bytes,
                                          retry_redundancy,
                                          retry_data,
                                          retry_parity,
                                          retry_blocks) ||
            retry_data == 0u || retry_parity < target_parity ||
            retry_parity <= candidate.parity) {
            return false;
        }
        encoded_redundancy = retry_redundancy;
    }
    if (!exact_budget_valid) return false;

    candidate.ratio = encoded_redundancy;
    candidate.requested_ratio = requested_redundancy;
    candidate.bits_per_page = bits_per_page;
    candidate.page_count = page_count;
    return true;
}

static bool find_best_ecc_fill(usize payload_bytes,
                               double min_ratio,
                               double max_ratio,
                               const ImageMappingConfig& mapping,
                               const PageFooterConfig& footer_config,
                               u32 width_pixels,
                               u32 height_pixels,
                               double structural_erasure_fraction,
                               bool reserve_overlay,
                               double& best_ratio,
                               double& best_requested_ratio,
                               u16& best_block_data,
                               u16& best_parity,
                               u64& best_frame_bits,
                               u64& best_bits_needed,
                               u64& best_page_count) {
    best_ratio = -1.0;
    best_requested_ratio = -1.0;
    best_block_data = 0u;
    best_parity = 0u;
    best_frame_bits = 0u;
    best_bits_needed = U64_MAX_VALUE;
    best_page_count = 0u;
    double search_low = min_ratio;
    double search_high = max_ratio;
    EccFillCandidate candidate;
    auto try_candidate = [&](double redundancy) -> bool {
        EccFillCandidate local;
        if (!evaluate_ecc_fill_candidate(payload_bytes,
                                          redundancy,
                                          mapping,
                                          footer_config,
                                          width_pixels,
                                          height_pixels,
                                          structural_erasure_fraction,
                                          reserve_overlay,
                                          local)) {
            return false;
        }
        u64 bits_remaining = (local.bits_per_page > local.frame_bits) ? (local.bits_per_page - local.frame_bits) : 0u;
        if (best_ratio < 0.0 ||
            local.page_count < best_page_count ||
            (local.page_count == best_page_count && bits_remaining < best_bits_needed) ||
            (local.page_count == best_page_count && bits_remaining == best_bits_needed && local.ratio < best_ratio)) {
            best_ratio = local.ratio;
            best_requested_ratio = local.requested_ratio;
            best_block_data = local.block_data;
            best_parity = local.parity;
            best_frame_bits = local.frame_bits;
            best_bits_needed = bits_remaining;
            best_page_count = local.page_count;
        }
        candidate = local;
        return true;
    };
    if (!try_candidate(search_low)) {
        return false;
    }
    for (u32 iteration = 0u; iteration < 64u; ++iteration) {
        double mid = (search_low + search_high) * 0.5;
        if (mid == search_low || mid == search_high) {
            break;
        }
        if (!evaluate_ecc_fill_candidate(payload_bytes,
                                          mid,
                                          mapping,
                                          footer_config,
                                          width_pixels,
                                          height_pixels,
                                          structural_erasure_fraction,
                                          reserve_overlay,
                                          candidate)) {
            search_high = mid;
            continue;
        }
        u64 bits_remaining = (candidate.bits_per_page > candidate.frame_bits) ? (candidate.bits_per_page - candidate.frame_bits) : 0u;
        if (best_ratio < 0.0 ||
            candidate.page_count < best_page_count ||
            (candidate.page_count == best_page_count && bits_remaining < best_bits_needed) ||
            (candidate.page_count == best_page_count && bits_remaining == best_bits_needed && candidate.ratio < best_ratio)) {
            best_ratio = candidate.ratio;
            best_requested_ratio = candidate.requested_ratio;
            best_block_data = candidate.block_data;
            best_parity = candidate.parity;
            best_frame_bits = candidate.frame_bits;
            best_bits_needed = bits_remaining;
            best_page_count = candidate.page_count;
        }
        if (candidate.page_count <= 1u) {
            search_low = mid;
        } else {
            search_high = mid;
        }
    }
    return (best_ratio >= 0.0);
}

static int command_encode(int arg_count, char** args) {
    if (arguments_request_help(arg_count, args)) {
        write_encode_help();
        return 0;
    }
    ImageMappingConfig mapping;
    PageFooterConfig footer_config;
    double ecc_redundancy = 0.2;
    static const usize MAX_INPUT_ITEMS = 512u;
    const char* input_paths[MAX_INPUT_ITEMS];
    usize input_count = 0u;
    makocode::ByteBuffer title_buffer;
    makocode::ByteBuffer filename_buffer;
    makocode::ByteBuffer password_buffer;
    makocode::ByteBuffer output_dir_buffer;
    makocode::ByteBuffer prefix_buffer;
    bool have_password = false;
    const char* output_dir = ".";
    bool have_output_dir = false;
    bool have_prefix = false;
    bool ecc_fill_requested = false;
    bool reserve_overlay = true;
    bool compact_page = false;
    bool debug_requested = false;
    for (int i = 0; i < arg_count; ++i) {
        bool handled = false;
        if (!process_image_mapping_option(arg_count, args, &i, mapping, "encode", &handled)) {
            return 1;
        }
        if (handled) {
            continue;
        }
        handled = false;
        if (!process_fiducial_option(arg_count, args, &i, g_fiducial_defaults, "encode", &handled)) {
            return 1;
        }
        if (handled) {
            continue;
        }
        const char* arg = args[i];
        if (!arg) {
            continue;
        }
        
        const char output_prefix[] = "--output-dir=";
        const char* output_value = 0;
        usize output_length = 0u;
        if (ascii_equals_token(arg, ascii_length(arg), "--output-dir")) {
            if (have_output_dir) {
                console_line(2, "encode: output directory specified multiple times");
                return 1;
            }
            if ((i + 1) >= arg_count) {
                console_line(2, "encode: --output-dir requires a non-empty path");
                return 1;
            }
            output_value = args[i + 1];
            output_length = ascii_length(output_value);
            i += 1;
        } else if (ascii_starts_with(arg, output_prefix)) {
            if (have_output_dir) {
                console_line(2, "encode: output directory specified multiple times");
                return 1;
            }
            output_value = arg + (sizeof(output_prefix) - 1u);
            output_length = ascii_length(output_value);
        }
        if (output_value) {
            if (output_length == 0u) {
                console_line(2, "encode: --output-dir requires a non-empty path");
                return 1;
            }
            if (!output_dir_buffer.ensure(output_length + 1u)) {
                console_line(2, "encode: failed to allocate output directory buffer");
                return 1;
            }
            for (usize j = 0u; j < output_length; ++j) {
                output_dir_buffer.data[j] = (u8)output_value[j];
            }
            output_dir_buffer.data[output_length] = 0u;
            output_dir_buffer.size = output_length;
            output_dir = (const char*)output_dir_buffer.data;
            have_output_dir = true;
            continue;
        }
        const char prefix_prefix[] = "--prefix=";
        const char* prefix_value = 0;
        usize prefix_length = 0u;
        if (ascii_equals_token(arg, ascii_length(arg), "--prefix")) {
            if (have_prefix) {
                console_line(2, "encode: --prefix specified multiple times");
                return 1;
            }
            if ((i + 1) >= arg_count) {
                console_line(2, "encode: --prefix requires a non-empty value");
                return 1;
            }
            prefix_value = args[i + 1];
            prefix_length = ascii_length(prefix_value);
            i += 1;
        } else if (ascii_starts_with(arg, prefix_prefix)) {
            if (have_prefix) {
                console_line(2, "encode: --prefix specified multiple times");
                return 1;
            }
            prefix_value = arg + (sizeof(prefix_prefix) - 1u);
            prefix_length = ascii_length(prefix_value);
        }
        if (prefix_value) {
            if (prefix_length == 0u) {
                console_line(2, "encode: --prefix requires a non-empty value");
                return 1;
            }
            if (!prefix_buffer.ensure(prefix_length + 1u)) {
                console_line(2, "encode: failed to allocate prefix buffer");
                return 1;
            }
            for (usize j = 0u; j < prefix_length; ++j) {
                char c = prefix_value[j];
                if (c == '/' || c == '\\') {
                    console_line(2, "encode: --prefix must not contain '/' or '\\\\'");
                    return 1;
                }
                prefix_buffer.data[j] = (u8)c;
            }
            prefix_buffer.data[prefix_length] = 0u;
            prefix_buffer.size = prefix_length;
            have_prefix = true;
            continue;
        }
        if (ascii_equals_token(arg, ascii_length(arg), "--no-filename")) {
            footer_config.display_filename = false;
            continue;
        }
        if (ascii_equals_token(arg, ascii_length(arg), "--no-page-count")) {
            footer_config.display_page_info = false;
            continue;
        }
        if (ascii_equals_token(arg, ascii_length(arg), "--compact-page")) {
            compact_page = true;
            continue;
        }
        if (ascii_equals_token(arg, ascii_length(arg), "--no-overlay-reserve")) {
            reserve_overlay = false;
            continue;
        }
        if (ascii_equals_token(arg, ascii_length(arg), "--debug")) {
            debug_requested = true;
            continue;
        }
        const char ecc_prefix[] = "--ecc=";
        const char* ecc_value = 0;
        usize ecc_length = 0u;
        if (ascii_equals_token(arg, ascii_length(arg), "--ecc")) {
            if ((i + 1) >= arg_count) {
                console_line(2, "encode: --ecc requires a numeric value");
                return 1;
            }
            ecc_value = args[i + 1];
            ecc_length = ascii_length(ecc_value);
            i += 1;
        } else if (ascii_starts_with(arg, ecc_prefix)) {
            ecc_value = arg + (sizeof(ecc_prefix) - 1u);
            ecc_length = ascii_length(ecc_value);
        }
        if (ecc_value) {
            if (ecc_length == 0u) {
                console_line(2, "encode: --ecc requires a numeric value");
                return 1;
            }
            double redundancy_value = 0.0;
            if (!ascii_to_double(ecc_value, ecc_length, &redundancy_value)) {
                console_line(2, "encode: --ecc value is not a valid decimal number");
                return 1;
            }
            ecc_redundancy = redundancy_value;
            continue;
        }
        if (ascii_equals_token(arg, ascii_length(arg), "--ecc-fill")) {
            ecc_fill_requested = true;
            continue;
        }
        const char input_prefix[] = "--input=";
        const char* input_value = 0;
        if (ascii_equals_token(arg, ascii_length(arg), "--input")) {
            if ((i + 1) >= arg_count) {
                console_line(2, "encode: --input requires a file path");
                return 1;
            }
            input_value = args[i + 1];
            if (input_value[0] == '\0') {
                console_line(2, "encode: --input requires a file path");
                return 1;
            }
            i += 1;
        } else if (ascii_starts_with(arg, input_prefix)) {
            input_value = arg + (sizeof(input_prefix) - 1u);
        }
        if (input_value) {
            if (input_value[0] == '\0') {
                console_line(2, "encode: --input requires a file path");
                return 1;
            }
            if (input_count >= MAX_INPUT_ITEMS) {
                console_line(2, "encode: too many input paths specified");
                return 1;
            }
            input_paths[input_count++] = input_value;
            continue;
        }
        const char title_prefix[] = "--title=";
        const char* title_value = 0;
        usize title_length = 0u;
        if (ascii_equals_token(arg, ascii_length(arg), "--title")) {
            if ((i + 1) >= arg_count) {
                console_line(2, "encode: --title requires a non-empty value");
                return 1;
            }
            title_value = args[i + 1];
            title_length = ascii_length(title_value);
            i += 1;
        } else if (ascii_starts_with(arg, title_prefix)) {
            title_value = arg + (sizeof(title_prefix) - 1u);
            title_length = ascii_length(title_value);
        }
        if (title_value) {
            if (title_length == 0u) {
                console_line(2, "encode: --title requires a non-empty value");
                return 1;
            }
            if (!title_buffer.ensure(title_length + 1u)) {
                console_line(2, "encode: failed to allocate title buffer");
                return 1;
            }
            for (usize j = 0u; j < title_length; ++j) {
                char c = title_value[j];
                if (!title_char_is_allowed(c)) {
                    console_line(2, "encode: title supports letters, digits, space, and !@#$%^&*()_+-={}[]:\";'<>?,./`~|\\");
                    return 1;
                }
                title_buffer.data[j] = (u8)c;
            }
            title_buffer.data[title_length] = 0u;
            title_buffer.size = title_length;
            footer_config.has_title = true;
            footer_config.title_length = title_length;
            footer_config.title_text = (const char*)title_buffer.data;
            continue;
        }
        const char font_prefix[] = "--font-size=";
        const char* font_value = 0;
        usize font_length = 0u;
        if (ascii_equals_token(arg, ascii_length(arg), "--font-size")) {
            if ((i + 1) >= arg_count) {
                console_line(2, "encode: --font-size requires a positive integer value");
                return 1;
            }
            font_value = args[i + 1];
            font_length = ascii_length(font_value);
            i += 1;
        } else if (ascii_starts_with(arg, font_prefix)) {
            font_value = arg + (sizeof(font_prefix) - 1u);
            font_length = ascii_length(font_value);
        }
        if (font_value) {
            if (font_length == 0u) {
                console_line(2, "encode: --font-size requires a positive integer value");
                return 1;
            }
            u64 value = 0u;
            if (!ascii_to_u64(font_value, font_length, &value) || value == 0u || value > 2048u) {
                console_line(2, "encode: --font-size must be between 1 and 2048");
                return 1;
            }
            footer_config.font_size = (u32)value;
            continue;
        }
        const char password_prefix[] = "--password=";
        const char* password_value = 0;
        usize password_length = 0u;
        if (ascii_equals_token(arg, ascii_length(arg), "--password")) {
            if (have_password) {
                console_line(2, "encode: password specified multiple times");
                return 1;
            }
            if ((i + 1) >= arg_count) {
                console_line(2, "encode: --password requires a non-empty value");
                return 1;
            }
            password_value = args[i + 1];
            password_length = ascii_length(password_value);
            i += 1;
        } else if (ascii_starts_with(arg, password_prefix)) {
            if (have_password) {
                console_line(2, "encode: password specified multiple times");
                return 1;
            }
            password_value = arg + (sizeof(password_prefix) - 1u);
            password_length = ascii_length(password_value);
        }
        if (password_value) {
            if (password_length == 0u) {
                console_line(2, "encode: --password requires a non-empty value");
                return 1;
            }
            if (!password_buffer.ensure(password_length)) {
                console_line(2, "encode: failed to allocate password buffer");
                return 1;
            }
            for (usize j = 0u; j < password_length; ++j) {
                password_buffer.data[j] = (u8)password_value[j];
            }
            password_buffer.size = password_length;
            have_password = true;
            continue;
        }
        console_write(2, "encode: unknown option: ");
        console_line(2, arg);
        return 1;
    }
    if (mapping.palette_set) {
        if (!image_mapping_build_custom_palette(mapping, "encode")) {
            return 1;
        }
        if (mapping.custom_palette_valid) {
            u32 background_index = 0u;
            u32 brightest_luminance = MetadataTile::rgb_luminance_u8(
                mapping.custom_palette[0u].r,
                mapping.custom_palette[0u].g,
                mapping.custom_palette[0u].b);
            for (u32 i = 1u; i < mapping.custom_palette_count; ++i) {
                u32 luminance = MetadataTile::rgb_luminance_u8(
                    mapping.custom_palette[i].r,
                    mapping.custom_palette[i].g,
                    mapping.custom_palette[i].b);
                if (luminance > brightest_luminance) {
                    brightest_luminance = luminance;
                    background_index = i;
                }
            }
            if (background_index > 0u) {
                PaletteColor reordered[MAX_CUSTOM_PALETTE_COLORS];
                u8 reordered_ids[MAX_CUSTOM_PALETTE_COLORS];
                for (u32 i = 0u; i < mapping.custom_palette_count; ++i) {
                    u32 source = (background_index + i) % mapping.custom_palette_count;
                    reordered[i] = mapping.custom_palette[source];
                    reordered_ids[i] = mapping.custom_palette_ids[source];
                }
                for (u32 i = 0u; i < mapping.custom_palette_count; ++i) {
                    mapping.custom_palette[i] = reordered[i];
                    mapping.custom_palette_ids[i] = reordered_ids[i];
                }
            }
        }
        // Downgrade custom palettes that exactly match built-in palettes so we
        // encode using the simpler fixed color modes (avoids palette-digit
        // packing for standard BW/CMYW/RGB pages).
        if (mapping.custom_palette_valid) {
            auto palette_matches = [&](const PaletteColor* builtin, u32 count) -> bool {
                if (!builtin || count == 0u || mapping.custom_palette_count != count) {
                    return false;
                }
                for (u32 i = 0u; i < count; ++i) {
                    const PaletteColor& a = mapping.custom_palette[i];
                    const PaletteColor& b = builtin[i];
                    if (a.r != b.r || a.g != b.g || a.b != b.b) {
                        return false;
                    }
                }
                return true;
            };
            bool background_first_gray = mapping.custom_palette_count == 2u &&
                mapping.custom_palette[0u].r == 255u &&
                mapping.custom_palette[0u].g == 255u &&
                mapping.custom_palette[0u].b == 255u &&
                mapping.custom_palette[1u].r == 0u &&
                mapping.custom_palette[1u].g == 0u &&
                mapping.custom_palette[1u].b == 0u;
            if (palette_matches(PALETTE_GRAY, (u32)(sizeof(PALETTE_GRAY) / sizeof(PALETTE_GRAY[0]))) ||
                background_first_gray) {
                mapping.color_channels = 1u;
                mapping.custom_palette_valid = false;
            } else if (palette_matches(PALETTE_CMYW, (u32)(sizeof(PALETTE_CMYW) / sizeof(PALETTE_CMYW[0])))) {
                mapping.color_channels = 2u;
                mapping.custom_palette_valid = false;
            } else if (palette_matches(PALETTE_RGB_CMY_WB, (u32)(sizeof(PALETTE_RGB_CMY_WB) / sizeof(PALETTE_RGB_CMY_WB[0])))) {
                mapping.color_channels = 3u;
                mapping.custom_palette_valid = false;
            }
        }
    }
    if (input_count == 0u) {
        console_line(2, "encode: at least one --input PATH is required");
        return 1;
    }
    ArchiveBuildContext archive;
    if (!archive_init(archive)) {
        console_line(2, "encode: failed to initialize archive buffer");
        return 1;
    }
    bool single_input = (input_count == 1u);
    makocode::ByteBuffer single_normalized;
    bool have_single_normalized = false;
    for (usize path_index = 0u; path_index < input_count; ++path_index) {
        const char* input_path = input_paths[path_index];
        struct stat path_info;
        if (stat(input_path, &path_info) != 0) {
            console_write(2, "encode: unable to stat ");
            console_line(2, input_path);
            return 1;
        }
        makocode::ByteBuffer normalized_path;
        if (!normalize_store_path(input_path, normalized_path)) {
            console_write(2, "encode: failed to normalize input path ");
            console_line(2, input_path);
            return 1;
        }
        const char* stored_rel = (const char*)normalized_path.data;
        if (S_ISDIR(path_info.st_mode)) {
            if (!archive_collect_directory(input_path, stored_rel, archive)) {
                return 1;
            }
        } else if (S_ISREG(path_info.st_mode)) {
            makocode::ByteBuffer file_data;
            if (!read_entire_file(input_path, file_data)) {
                console_write(2, "encode: failed to read ");
                console_line(2, input_path);
                return 1;
            }
            if (!archive_add_file(archive, stored_rel, file_data.data, file_data.size)) {
                file_data.release();
                return 1;
            }
            file_data.release();
        } else {
            console_write(2, "encode: unsupported input type for ");
            console_line(2, input_path);
            return 1;
        }
        if (single_input && !have_single_normalized) {
            if (!single_normalized.ensure(normalized_path.size + 1u)) {
                console_line(2, "encode: failed to record normalized path");
                return 1;
            }
            for (usize j = 0u; j < normalized_path.size; ++j) {
                single_normalized.data[j] = normalized_path.data[j];
            }
            single_normalized.data[normalized_path.size] = 0u;
            single_normalized.size = normalized_path.size;
            have_single_normalized = true;
        }
    }
    if (archive.entry_count == 0u) {
        console_line(2, "encode: no files or directories to encode");
        return 1;
    }
    if (!archive_finalize(archive)) {
        console_line(2, "encode: failed to finalize archive");
        return 1;
    }
    footer_config.filename_text = 0;
    footer_config.filename_length = 0u;
    footer_config.has_filename = false;
    if (footer_config.display_filename) {
        if (single_input && have_single_normalized) {
            const char* base_name = find_last_path_component((const char*)single_normalized.data);
            usize base_length = ascii_length(base_name);
            if (!filename_buffer.ensure(base_length + 1u)) {
                console_line(2, "encode: failed to allocate filename buffer");
                return 1;
            }
            for (usize j = 0u; j < base_length; ++j) {
                char c = base_name[j];
                if (!title_char_is_allowed(c)) {
                    console_line(2, "encode: filename contains unsupported characters for footer text");
                    return 1;
                }
                filename_buffer.data[j] = (u8)c;
            }
            filename_buffer.data[base_length] = 0u;
            filename_buffer.size = base_length;
            footer_config.filename_text = (const char*)filename_buffer.data;
            footer_config.filename_length = base_length;
            footer_config.has_filename = true;
        } else {
            const char bundle_label[] = "bundle";
            usize label_length = (usize)(sizeof(bundle_label) - 1u);
            if (!filename_buffer.ensure(label_length + 1u)) {
                console_line(2, "encode: failed to allocate filename buffer");
                return 1;
            }
            for (usize j = 0u; j < label_length; ++j) {
                filename_buffer.data[j] = (u8)bundle_label[j];
            }
            filename_buffer.data[label_length] = 0u;
            filename_buffer.size = label_length;
            footer_config.filename_text = (const char*)filename_buffer.data;
            footer_config.filename_length = label_length;
            footer_config.has_filename = true;
        }
    }
    u32 width_pixels = 0u;
    u32 height_pixels = 0u;
    compute_page_dimensions(mapping, width_pixels, height_pixels);
    makocode::ByteBuffer compressed_for_sizing;
    if (!lzma_compress(archive.buffer.data,
                       archive.buffer.size,
                       compressed_for_sizing,
                       false)) {
        console_line(2, "encode: failed to compress payload for ECC sizing");
        return 1;
    }
    usize ecc_payload_bytes = compressed_for_sizing.size;
    compressed_for_sizing.release();
    if (have_password) {
        usize encryption_overhead = makocode::ENCRYPTION_HEADER_BYTES + makocode::ENCRYPTION_TAG_BYTES;
        if (ecc_payload_bytes > USIZE_MAX_VALUE - encryption_overhead) {
            console_line(2, "encode: encrypted payload size overflow");
            return 1;
        }
        ecc_payload_bytes += encryption_overhead;
    }
    double structural_erasure_fraction = 0.0;
    double unknown_error_redundancy = ecc_redundancy;
    u16 unknown_parity_budget = 0u;
    u16 overlay_erasure_budget = 0u;
    if (width_pixels < MetadataTile::TILE_SIDE || height_pixels < MetadataTile::TILE_SIDE) {
        console_line(2, "encode: canonical centered metadata tile requires a page at least 48x48");
        return 1;
    }
    PageFooterConfig estimate_footer_config = footer_config;
    estimate_footer_config.max_text_length = footer_compute_max_text_length(estimate_footer_config, 1u);
    FooterLayout estimate_footer_layout;
    makocode::ByteBuffer canonical_mask;
    u64 canonical_reserved = 0u;
    if (!compute_footer_layout(width_pixels,
                               height_pixels,
                               estimate_footer_config,
                               estimate_footer_layout) ||
        estimate_footer_layout.data_height_pixels < MetadataTile::TILE_SIDE ||
        !compute_fiducial_marker_mask(width_pixels,
                                      height_pixels,
                                      estimate_footer_layout.data_height_pixels,
                                      canonical_reserved,
                                      &canonical_mask,
                                      false,
                                      0u,
                                      0u,
                                      0u,
                                      0u)) {
        console_line(2, "encode: canonical centered metadata layout does not fit page geometry");
        return 1;
    }
    u64 overwritten_pixels = 0u;
    for (usize i = 0u; i < canonical_mask.size; ++i) {
        if (canonical_mask.data[i] == OVERWRITE_MASK_PIXEL) {
            ++overwritten_pixels;
        }
    }
    u64 data_pixels = (u64)width_pixels *
                      (u64)estimate_footer_layout.data_height_pixels;
    if (data_pixels == 0u || overwritten_pixels == 0u) {
        console_line(2, "encode: canonical layout has no payload capacity");
        return 1;
    }
    structural_erasure_fraction =
        mapping_has_custom_palette(mapping) &&
                !is_power_of_two_u32(mapping.custom_palette_count)
            ? 0.0
            : (double)overwritten_pixels / (double)data_pixels;
    if (ecc_fill_requested) {
        double best_ratio = -1.0;
        double best_requested_ratio = -1.0;
        u16 best_block_data = 0u;
        u16 best_parity = 0u;
        u64 best_frame_bits = 0u;
        u64 best_bits_needed = 0u;
        u64 best_page_count = 0u;
        bool found_fill = find_best_ecc_fill(ecc_payload_bytes,
                                ecc_redundancy,
                                (double)makocode::RS_FIELD_SIZE,
                                mapping,
                                footer_config,
                                width_pixels,
                                height_pixels,
                                structural_erasure_fraction,
                                reserve_overlay,
                                best_ratio,
                                best_requested_ratio,
                                best_block_data,
                                best_parity,
                                best_frame_bits,
                                best_bits_needed,
                                best_page_count);
        if (!found_fill) {
            console_line(2, "encode: failed to derive ECC fill candidate");
            return 1;
        }
        double derived_redundancy = 0.0;
        if (!derive_ecc_redundancy_with_overwrite(ecc_payload_bytes,
                                           best_requested_ratio,
                                           structural_erasure_fraction,
                                           derived_redundancy,
                                           unknown_parity_budget,
                                           overlay_erasure_budget,
                                           reserve_overlay)) {
            console_line(2, "encode: canonical ECC fill cannot preserve structural and unknown-error budgets");
            return 1;
        }
        unknown_error_redundancy = best_requested_ratio;
        char ratio_buffer[32];
        format_fixed_3(best_ratio, ratio_buffer, sizeof(ratio_buffer));
        char block_buffer[32];
        u64_to_ascii(best_block_data, block_buffer, sizeof(block_buffer));
        char parity_buffer[32];
        u64_to_ascii(best_parity, parity_buffer, sizeof(parity_buffer));
        char bits_buffer[32];
        u64_to_ascii(best_bits_needed, bits_buffer, sizeof(bits_buffer));
        char page_buffer[32];
        u64_to_ascii(best_page_count, page_buffer, sizeof(page_buffer));
        console_write(1, "encode: --ecc-fill -> --ecc=");
        console_write(1, ratio_buffer);
        console_write(1, " (blocks=");
        console_write(1, block_buffer);
        console_write(1, " parity=");
        console_write(1, parity_buffer);
        console_write(1, " pages=");
        console_write(1, page_buffer);
        console_write(1, " bits_needed=");
        console_write(1, bits_buffer);
        console_line(1, ")");
        ecc_redundancy = best_ratio;
    } else {
        double derived_redundancy = 0.0;
        if (!derive_ecc_redundancy_with_overwrite(ecc_payload_bytes,
                                           unknown_error_redundancy,
                                           ecc_fill_requested
                                               ? structural_erasure_fraction
                                               : 0.0,
                                           derived_redundancy,
                                           unknown_parity_budget,
                                           overlay_erasure_budget,
                                           reserve_overlay)) {
            console_line(2, "encode: requested ECC cannot preserve structural and unknown-error budgets");
            return 1;
        } else {
            ecc_redundancy = derived_redundancy;
        }
    }
    makocode::EncoderContext encoder;
    encoder.config.ecc_redundancy = ecc_redundancy;
    if (have_password) {
        if (!encoder.set_password((const char*)password_buffer.data, password_buffer.size)) {
            console_line(2, "encode: failed to set encryption password");
            return 1;
        }
    }
    if (!encoder.set_payload(archive.buffer.data, archive.buffer.size)) {
        console_line(2, "encode: failed to set payload");
        return 1;
    }
    if (!encoder.build()) {
        console_line(2, "encode: build failed");
        return 1;
    }
    if (debug_requested) {
        char data_buffer[32];
        char parity_buffer[32];
        u64_to_ascii(encoder.ecc_info().block_data_symbols, data_buffer, sizeof(data_buffer));
        u64_to_ascii(encoder.ecc_info().parity_symbols, parity_buffer, sizeof(parity_buffer));
        console_write(1, "debug: ECC data symbols=");
        console_write(1, data_buffer);
        console_write(1, " parity symbols=");
        console_line(1, parity_buffer);
    }
    makocode::ByteBuffer frame_bits;
    u64 frame_bit_count = 0u;
    if (!build_frame_bits(encoder, mapping, frame_bits, frame_bit_count)) {
        console_line(2, "encode: failed to build frame");
        return 1;
    }
    FooterLayout footer_layout;
    u32 layout_data_height = height_pixels;
    u64 bits_per_page = 0u;
    u64 page_count = 0u;
    if (!compute_page_layout(mapping,
                             footer_config,
                             frame_bit_count,
                             width_pixels,
                             height_pixels,
                             footer_layout,
                             layout_data_height,
                             bits_per_page,
                             page_count)) {
        console_line(2, "encode: footer layout did not converge");
        return 1;
    }
    bool overwrite_budget_valid = false;
    for (u32 parity_attempt = 0u;
         parity_attempt < makocode::RS_FIELD_SIZE;
         ++parity_attempt) {
        u16 required_parity = 0u;
        bool current_budget_valid = validate_overwrite_budget(mapping,
                                                              frame_bits,
                                                              frame_bit_count,
                                                              width_pixels,
                                                              height_pixels,
                                                              layout_data_height,
                                                              bits_per_page,
                                                              page_count,
                                                              encoder.ecc_info(),
                                                              unknown_parity_budget,
                                                              overlay_erasure_budget,
                                                              &required_parity);
        if (current_budget_valid) {
            overwrite_budget_valid = true;
            break;
        }
        u16 current_parity = encoder.ecc_info().parity_symbols;
        if (!required_parity || required_parity >= makocode::RS_FIELD_SIZE - 1u) {
            break;
        }

        // The geometric estimate above is only a starting point. Raise parity
        // to the exact worst-block requirement after mapping overwrites through
        // the payload shuffle, then rebuild and recount because block boundaries
        // and the shuffle length change with parity.
        u16 target_parity = (u16)(required_parity + 1u);
        if (target_parity <= current_parity) break;
        double retry_redundancy = ecc_payload_bytes < makocode::RS_FIELD_SIZE &&
                                          target_parity <=
                                              (u64)makocode::RS_FIELD_SIZE - ecc_payload_bytes
                                      ? (double)target_parity / (double)ecc_payload_bytes
                                      : ((double)target_parity - 0.5) /
                                            ((double)makocode::RS_FIELD_SIZE -
                                             (double)target_parity);
        u16 retry_data = 0u;
        u16 retry_parity = 0u;
        u64 retry_blocks = 0u;
        if (!makocode::compute_ecc_layout(ecc_payload_bytes,
                                          retry_redundancy,
                                          retry_data,
                                          retry_parity,
                                          retry_blocks) ||
            retry_data == 0u || retry_parity < target_parity ||
            retry_parity <= current_parity) {
            break;
        }

        ecc_redundancy = retry_redundancy;
        encoder.config.ecc_redundancy = retry_redundancy;
        if (!encoder.build() ||
            !build_frame_bits(encoder, mapping, frame_bits, frame_bit_count) ||
            !compute_page_layout(mapping,
                                 footer_config,
                                 frame_bit_count,
                                 width_pixels,
                                 height_pixels,
                                 footer_layout,
                                 layout_data_height,
                                 bits_per_page,
                                 page_count)) {
            break;
        }
    }
    if (!overwrite_budget_valid) {
        console_line(2, "encode: canonical layout cannot satisfy the exact structural erasure budget");
        return 1;
    }
    char timestamp_name[32];
    const char* page_name_prefix = 0;
    if (have_prefix) {
        page_name_prefix = (const char*)prefix_buffer.data;
    } else {
        if (!utc_timestamp_string(timestamp_name, sizeof(timestamp_name))) {
            console_line(2, "encode: failed to construct timestamped filename");
            return 1;
        }
        page_name_prefix = timestamp_name;
    }
    bool debug_reapplied_by_filename = debug_requested &&
                                       path_contains_substring(page_name_prefix, "_encoded");
    makocode::ByteBuffer debug_fiducial_csv;
    makocode::ByteBuffer debug_fiducial_path;
    if (debug_requested) {
        if (!debug_fiducial_csv.append_ascii("page,row,column,x,y,logical_x,logical_y\n")) {
            console_line(2, "encode: failed to prepare fiducial CSV");
            return 1;
        }
        makocode::ByteBuffer debug_fiducial_name;
        if (!debug_fiducial_name.append_ascii(page_name_prefix) ||
            !debug_fiducial_name.append_ascii("_encode_fiducials.csv") ||
            !join_output_path(output_dir,
                              (const char*)debug_fiducial_name.data,
                              debug_fiducial_path)) {
            console_line(2, "encode: failed to prepare fiducial CSV path");
            return 1;
        }
    }
    makocode::ByteBuffer footer_text_buffer;
    const makocode::EccSummary* ecc_summary = &encoder.ecc_info();
    if (page_count == 1u) {
        u32 output_height_pixels = height_pixels;
        FooterLayout output_footer_layout = footer_layout;
        u32 output_data_height_pixels = layout_data_height;
        u64 output_bits_per_page = bits_per_page;

        if (compact_page && footer_layout.has_text) {
            console_line(2, "encode: --compact-page requires the footer text to be disabled (use --no-filename and --no-page-count, and omit --title)");
            return 1;
        }

        // For single-page outputs with no footer text, shrink to the minimum
        // height needed for payload data.
        if (compact_page && !footer_layout.has_text && layout_data_height > 0u) {
            double bits_per_pixel = mapping_bits_per_data_pixel(mapping);
            if (bits_per_pixel > 0.0) {
                u32 max_data_height = layout_data_height;
                if (max_data_height > 0u) {
                    u32 low = 1u;
                    u32 high = max_data_height;
                    u32 best = max_data_height;
                    u64 best_bits = 0u;
                    while (low <= high) {
                        u32 mid = low + (high - low) / 2u;
                        u64 candidate_bits = 0u;
                        if (compute_bits_per_page(mapping,
                                                  width_pixels,
                                                  height_pixels,
                                                  mid,
                                                  candidate_bits) &&
                            candidate_bits >= frame_bit_count) {
                            best = mid;
                            best_bits = candidate_bits;
                            high = mid - 1u;
                        } else {
                            low = mid + 1u;
                        }
                    }
                    if (best_bits > 0u) {
                        bool exact_budget_fit = false;
                        for (u32 candidate_height = best;
                             candidate_height <= max_data_height;
                             ++candidate_height) {
                            u64 candidate_bits = 0u;
                            if (!compute_bits_per_page(mapping,
                                                       width_pixels,
                                                       height_pixels,
                                                       candidate_height,
                                                       candidate_bits) ||
                                candidate_bits < frame_bit_count) {
                                continue;
                            }
                            if (validate_overwrite_budget(mapping,
                                                          frame_bits,
                                                          frame_bit_count,
                                                          width_pixels,
                                                          candidate_height,
                                                          candidate_height,
                                                          candidate_bits,
                                                          1u,
                                                          encoder.ecc_info(),
                                                          unknown_parity_budget,
                                                          overlay_erasure_budget,
                                                          (u16*)0)) {
                                best = candidate_height;
                                best_bits = candidate_bits;
                                exact_budget_fit = true;
                                break;
                            }
                        }
                        if (!exact_budget_fit) best_bits = 0u;
                    }
                    // Only apply if it meaningfully reduces the unused band.
                    if (best_bits > 0u && best + 4u < layout_data_height) {
                        output_height_pixels = best;
                        output_footer_layout.data_height_pixels = best;
                        output_data_height_pixels = best;
                        // Bits-per-page depends on data_height; keep it consistent with
                        // the chosen data height even when we shrink the output image.
                        output_bits_per_page = best_bits;
                    }
                }
            }
        }
        makocode::ByteBuffer page_output;
        if (!footer_build_page_text(footer_config, 1u, page_count, footer_text_buffer)) {
            console_line(2, "encode: failed to build footer text");
            return 1;
        }
        const char* footer_text = output_footer_layout.has_text ? (const char*)footer_text_buffer.data : 0;
        usize footer_length = output_footer_layout.has_text ? footer_text_buffer.size : 0u;
        if (!encode_page_to_ppm(mapping,
                                frame_bits,
                                frame_bit_count,
                                0u,
                                width_pixels,
                                output_height_pixels,
                                1u,
                                1u,
                                output_bits_per_page,
                                ecc_summary,
                                footer_text,
                                footer_length,
                                output_footer_layout,
                                page_output,
                                unknown_parity_budget,
                                overlay_erasure_budget)) {
           console_line(2, "encode: failed to format ppm");
           return 1;
       }
        makocode::ByteBuffer fiducial_page;
        // Clip fiducials to the data area so they don't overlap footer text.
        if (!apply_default_fiducial_grid(page_output,
                                         fiducial_page,
                                         output_data_height_pixels,
                                         (debug_requested && !debug_reapplied_by_filename)
                                             ? &debug_fiducial_csv
                                             : (makocode::ByteBuffer*)0,
                                         1u)) {
            console_line(2, "encode: failed to embed fiducial grid");
            return 1;
        }
        byte_buffer_move(page_output, fiducial_page);
        makocode::ByteBuffer output_name;
        makocode::ByteBuffer output_path;
        if (!build_page_filename(output_name, page_name_prefix, 1u, 1u)) {
            console_line(2, "encode: failed to build output filename");
            return 1;
        }
        if (!join_output_path(output_dir, (const char*)output_name.data, output_path)) {
            console_line(2, "encode: failed to prepare output path");
            return 1;
        }
        if (!ensure_parent_directories((const char*)output_path.data)) {
            console_line(2, "encode: failed to prepare output directories");
            return 1;
        }
        if (!write_buffer_to_file((const char*)output_path.data,
                                  page_output,
                                  debug_reapplied_by_filename ? &debug_fiducial_csv : (makocode::ByteBuffer*)0,
                                  1u,
                                  output_data_height_pixels)) {
            console_line(2, "encode: failed to write ppm file");
            return 1;
        }
        console_write(1, "encode: wrote 1 page (");
        console_write(1, (const char*)output_path.data);
        console_line(1, ")");
    } else {
        makocode::ByteBuffer name_buffer;
        makocode::ByteBuffer path_buffer;
        for (u64 page = 0u; page < page_count; ++page) {
            makocode::ByteBuffer page_output;
            u64 bit_offset = page * bits_per_page;
            if (!footer_build_page_text(footer_config, page + 1u, page_count, footer_text_buffer)) {
                console_line(2, "encode: failed to build footer text");
                return 1;
            }
            const char* footer_text = footer_layout.has_text ? (const char*)footer_text_buffer.data : 0;
            usize footer_length = footer_layout.has_text ? footer_text_buffer.size : 0u;
            if (!encode_page_to_ppm(mapping,
                                    frame_bits,
                                    frame_bit_count,
                                    bit_offset,
                                    width_pixels,
                                    height_pixels,
                                    page + 1u,
                                    page_count,
                                    bits_per_page,
                                    ecc_summary,
                                    footer_text,
                                    footer_length,
                                    footer_layout,
                                    page_output,
                                    unknown_parity_budget,
                                    overlay_erasure_budget)) {
                console_line(2, "encode: failed to format ppm page");
                return 1;
            }
            makocode::ByteBuffer fiducial_page;
            // Clip fiducials to the data area so they don't overlap footer text.
            if (!apply_default_fiducial_grid(page_output,
                                             fiducial_page,
                                             footer_layout.data_height_pixels,
                                             (debug_requested && !debug_reapplied_by_filename)
                                                 ? &debug_fiducial_csv
                                                 : (makocode::ByteBuffer*)0,
                                             page + 1u)) {
                console_line(2, "encode: failed to embed fiducial grid");
                return 1;
            }
            byte_buffer_move(page_output, fiducial_page);
            if (!build_page_filename(name_buffer, page_name_prefix, page + 1u, page_count)) {
                console_line(2, "encode: failed to build filename");
                return 1;
            }
            if (!join_output_path(output_dir, (const char*)name_buffer.data, path_buffer)) {
                console_line(2, "encode: failed to prepare output path");
                return 1;
            }
            if (!ensure_parent_directories((const char*)path_buffer.data)) {
                console_line(2, "encode: failed to prepare output directories");
                return 1;
            }
            if (!write_buffer_to_file((const char*)path_buffer.data,
                                      page_output,
                                      debug_reapplied_by_filename ? &debug_fiducial_csv : (makocode::ByteBuffer*)0,
                                      page + 1u,
                                      footer_layout.data_height_pixels)) {
                console_line(2, "encode: failed to write ppm file");
                return 1;
            }
        }
        makocode::ByteBuffer sample_name;
        if (!build_page_filename(sample_name, page_name_prefix, 1u, page_count)) {
            console_line(2, "encode: failed to summarize filenames");
            return 1;
        }
        makocode::ByteBuffer sample_path;
        const char* summary_name = (const char*)sample_name.data;
        if (join_output_path(output_dir, summary_name, sample_path)) {
            summary_name = (const char*)sample_path.data;
        }
        char digits[32];
        u64_to_ascii(page_count, digits, sizeof(digits));
        console_write(1, "encode: wrote ");
        console_write(1, digits);
        console_write(1, " pages (");
        console_write(1, summary_name);
        console_line(1, " ...)");
    }
    if (debug_requested &&
        (!ensure_parent_directories((const char*)debug_fiducial_path.data) ||
         !write_bytes_to_file((const char*)debug_fiducial_path.data,
                              debug_fiducial_csv.data,
                              debug_fiducial_csv.size))) {
        console_line(2, "encode: failed to write fiducial CSV");
        return 1;
    }
    return 0;
}

struct OverlayPage {
    makocode::ByteBuffer original;
    makocode::ByteBuffer pixels;
    PpmParserState      metadata;
    u32                 width;
    u32                 height;
    u32                 data_height;
    u32                 footer_rows;
    u8                  color_mode;
    bool                use_custom_palette;
    ImageMappingConfig  custom_mapping;
    u8                  custom_symbol_bits;

    OverlayPage()
        : original(),
          pixels(),
          metadata(),
          width(0u),
          height(0u),
          data_height(0u),
          footer_rows(0u),
          color_mode(1u),
          use_custom_palette(false),
          custom_mapping(),
          custom_symbol_bits(0u) {}

    ~OverlayPage() {
        original.release();
        pixels.release();
        metadata = PpmParserState();
        width = 0u;
        height = 0u;
        data_height = 0u;
        footer_rows = 0u;
        color_mode = 1u;
        use_custom_palette = false;
        custom_symbol_bits = 0u;
    }
};

static const usize MAX_OVERLAY_IGNORE_COLORS = 64u;

struct OverlayIgnoreColorList {
    PaletteColor colors[MAX_OVERLAY_IGNORE_COLORS];
    usize count;
};

// The overlay PPM that carries the mask rarely encodes layout metadata such as
// footer rows or fiducial sizing. When that metadata is absent we still need the
// overlay to line up pixel-for-pixel with the base page so that the merged image
// doesn't appear shifted. Synchronize the layout-critical fields from the base
// page onto the overlay before we build masks or gather bits.
static void overlay_apply_base_layout(const OverlayPage& base, OverlayPage& overlay) {
    overlay.footer_rows = base.footer_rows;
    overlay.data_height = overlay.height - overlay.footer_rows;
    if (base.metadata.has_footer_rows) {
        overlay.metadata.has_footer_rows = true;
        overlay.metadata.footer_rows_value = base.metadata.footer_rows_value;
    }
    if (base.metadata.has_fiducial_size) {
        overlay.metadata.has_fiducial_size = true;
        overlay.metadata.fiducial_size_value = base.metadata.fiducial_size_value;
    }
    if (base.metadata.has_fiducial_margin) {
        overlay.metadata.has_fiducial_margin = true;
        overlay.metadata.fiducial_margin_value = base.metadata.fiducial_margin_value;
    }
    if (base.metadata.has_fiducial_columns) {
        overlay.metadata.has_fiducial_columns = true;
        overlay.metadata.fiducial_columns_value = base.metadata.fiducial_columns_value;
    }
    if (base.metadata.has_fiducial_rows) {
        overlay.metadata.has_fiducial_rows = true;
        overlay.metadata.fiducial_rows_value = base.metadata.fiducial_rows_value;
    }
    if (base.metadata.has_encoded_tile) {
        overlay.metadata.has_encoded_tile = true;
        overlay.metadata.encoded_tile = base.metadata.encoded_tile;
    }
}

static bool overlay_ignore_char_is_delimiter(char c) {
    switch (c) {
        case ' ':
        case '\t':
        case '\n':
        case '\r':
        case ',':
        case ';':
            return true;
        default:
            return false;
    }
}

static bool overlay_color_matches_ignore(const OverlayIgnoreColorList& list,
                                        u8 r,
                                        u8 g,
                                        u8 b) {
    for (usize i = 0u; i < list.count; ++i) {
        const PaletteColor& candidate = list.colors[i];
        if (candidate.r == r && candidate.g == g && candidate.b == b) {
            return true;
        }
    }
    return false;
}

static bool parse_overlay_ignore_colors(const char* text,
                                        usize length,
                                        OverlayIgnoreColorList& list) {
    list.count = 0u;
    usize cursor = 0u;
    while (cursor < length) {
        while (cursor < length && overlay_ignore_char_is_delimiter(text[cursor])) {
            ++cursor;
        }
        if (cursor >= length) {
            break;
        }
        usize start = cursor;
        while (cursor < length && !overlay_ignore_char_is_delimiter(text[cursor])) {
            ++cursor;
        }
        usize token_length = cursor - start;
        if (list.count >= MAX_OVERLAY_IGNORE_COLORS) {
            console_line(2, "overlay: --ignore-colors supports at most 64 entries");
            return false;
        }
        PaletteColor color;
        u8 color_id = NAMED_COLOR_INVALID;
        if (!decode_named_palette_color(text + start, token_length, color_id, color)) {
            console_line(2, "overlay: --ignore-colors contains an invalid color");
            return false;
        }
        bool duplicate = false;
        for (usize i = 0u; i < list.count; ++i) {
            if (palette_colors_equal(list.colors[i], color)) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) {
            continue;
        }
        list.colors[list.count++] = color;
    }
    return true;
}

static bool load_overlay_page(const char* path, OverlayPage& page) {
    page.original.release();
    page.pixels.release();
    page.metadata = PpmParserState();
    page.width = 0u;
    page.height = 0u;
    page.data_height = 0u;
    page.footer_rows = 0u;
    page.color_mode = 1u;
    page.use_custom_palette = false;
    page.custom_symbol_bits = 0u;
    if (!read_entire_file(path, page.original)) {
        console_write(2, "overlay: failed to read ");
        console_line(2, path);
        return false;
    }
    if (!page.original.data || page.original.size == 0u) {
        console_write(2, "overlay: empty file ");
        console_line(2, path);
        return false;
    }
    PpmParserState state;
    state.data = page.original.data;
    state.size = page.original.size;
    const char* token = 0;
    usize token_length = 0u;
    if (!ppm_next_token(state, &token, &token_length) ||
        !ascii_equals_token(token, token_length, "P6")) {
        console_write(2, "overlay: ");
        console_write(2, path);
        console_line(2, " is not a P6 binary PPM");
        return false;
    }
    u64 width_value = 0u;
    if (!ppm_next_token(state, &token, &token_length) ||
        !ascii_to_u64(token, token_length, &width_value) ||
        width_value == 0u ||
        width_value > 0xFFFFFFFFull) {
        console_write(2, "overlay: invalid width in ");
        console_line(2, path);
        return false;
    }
    u64 height_value = 0u;
    if (!ppm_next_token(state, &token, &token_length) ||
        !ascii_to_u64(token, token_length, &height_value) ||
        height_value == 0u ||
        height_value > 0xFFFFFFFFull) {
        console_write(2, "overlay: invalid height in ");
        console_line(2, path);
        return false;
    }
    u64 max_value = 0u;
    if (!ppm_next_token(state, &token, &token_length) ||
        !ascii_to_u64(token, token_length, &max_value) ||
        max_value != 255u ||
        width_value > U64_MAX_VALUE / height_value ||
        width_value * height_value > (u64)USIZE_MAX_VALUE / 3u ||
        !ppm_consume_binary_separator(state)) {
        console_write(2, "overlay: unsupported max pixel value in ");
        console_line(2, path);
        return false;
    }
    u64 pixel_count = width_value * height_value;
    if (pixel_count > ((u64)USIZE_MAX_VALUE / 3u)) {
        console_write(2, "overlay: pixel count overflow in ");
        console_line(2, path);
        return false;
    }
    makocode::ByteBuffer pixel_data;
    if (!ppm_read_rgb_pixels(state, pixel_count, pixel_data)) {
        console_write(2, "overlay: failed to parse pixel data from ");
        console_line(2, path);
        return false;
    }
    page.metadata = state;
    page.metadata.data = 0;
    page.metadata.size = 0u;
    page.metadata.cursor = 0u;

    // The canonical protected tile is centered in the logical data area.
    MetadataTile::Values tile_values = {};
    makocode::ByteBuffer tile_palette_text;
    u32 hinted_footer_rows = page.metadata.has_footer_rows &&
                                     page.metadata.footer_rows_value <= height_value
                                 ? (u32)page.metadata.footer_rows_value
                                 : 0u;
    u32 hinted_data_height = (u32)height_value - hinted_footer_rows;
    const u32 data_height_offsets[] = {0u, 8u, 16u, 24u, 32u};
    for (u32 offset_index = 0u;
         offset_index < sizeof(data_height_offsets) / sizeof(data_height_offsets[0]) &&
         !page.metadata.has_encoded_tile;
         ++offset_index) {
        u32 candidate_data_height = hinted_data_height;
        if (offset_index > 0u) {
            u32 offset = data_height_offsets[offset_index];
            if (offset >= candidate_data_height) continue;
            candidate_data_height -= offset;
        }
        if (candidate_data_height < MetadataTile::TILE_SIDE) continue;
        MetadataTile::Placement center_placement =
            MetadataTile::compute_center_tile_placement((u32)width_value, candidate_data_height);
        bool decoded = center_placement.valid &&
                       MetadataTile::decode_tile(pixel_data.data,
                                                 (u32)width_value,
                                                 (u32)height_value,
                                                 candidate_data_height,
                                                 center_placement,
                                                 tile_values,
                                                 tile_palette_text);
        if (decoded) {
            apply_metadata_tile_metadata(page.metadata, tile_values, tile_palette_text);
        }
    }

    byte_buffer_move(page.pixels, pixel_data);
    page.width = (u32)width_value;
    page.height = (u32)height_value;

    u32 footer_rows = 0u;
    if (page.metadata.has_footer_rows) {
        if (page.metadata.footer_rows_value > height_value) {
            console_write(2, "overlay: footer metadata exceeds image height in ");
            console_line(2, path);
            return false;
        }
        footer_rows = (u32)page.metadata.footer_rows_value;
    }
    page.footer_rows = footer_rows;
    page.data_height = page.height - footer_rows;
    page.color_mode = 1u;
    if (page.metadata.has_palette_base) {
        const u64 palette_base = page.metadata.palette_base_value;
        if (palette_base >= 8u) {
            page.color_mode = 3u;
        } else if (palette_base >= 4u) {
            page.color_mode = 2u;
        }
    } else if (page.pixels.data && page.pixels.size >= (usize)page.width * (usize)page.height * 3u) {
        // When palette metadata is unavailable (e.g., synthetic overlay masks),
        // infer whether the image uses chroma at all. Overlay behavior only
        // needs a coarse "grayscale vs. color" distinction to decide between
    // raw-pixel overlay and data-bit overlay. Avoid depending on container metadata
        // comments, which are not preserved across print/scan workflows.
        usize total_pixels = (usize)page.width * (usize)page.height;
        bool has_color = false;
        for (usize i = 0u; i < total_pixels; ++i) {
            const u8* rgb = page.pixels.data + i * 3u;
            if (rgb[0] != rgb[1] || rgb[1] != rgb[2]) {
                has_color = true;
                break;
            }
        }
        if (has_color) {
            page.color_mode = 2u;
        }
    }
    bool palette_matches_builtin = false;
    u8 builtin_mode = 1u;
    if (page.metadata.has_encoded_tile) {
        const MetadataTile::Values& values = page.metadata.encoded_tile;
        auto matches_palette = [&](const PaletteColor* builtin, u32 count, u8 mode) -> bool {
            if (!builtin || values.palette_count != count) return false;
            for (u32 i = 0u; i < count; ++i) {
                if (!palette_colors_equal(values.palette[i], builtin[i])) return false;
            }
            builtin_mode = mode;
            return true;
        };
        palette_matches_builtin =
            matches_palette(PALETTE_GRAY,
                            (u32)(sizeof(PALETTE_GRAY) / sizeof(PALETTE_GRAY[0])),
                            1u) ||
            matches_palette(PALETTE_CMYW,
                            (u32)(sizeof(PALETTE_CMYW) / sizeof(PALETTE_CMYW[0])),
                            2u) ||
            matches_palette(PALETTE_RGB_CMY_WB,
                            (u32)(sizeof(PALETTE_RGB_CMY_WB) /
                                  sizeof(PALETTE_RGB_CMY_WB[0])),
                            3u);
        if (palette_matches_builtin) page.color_mode = builtin_mode;
    }
    bool should_use_custom = page.metadata.has_palette_base ||
                             (page.metadata.has_encoded_tile && !palette_matches_builtin);
    if (should_use_custom && page.metadata.has_palette_text &&
        page.metadata.palette_text_length > 0u &&
        image_mapping_set_palette_text(page.custom_mapping,
                                       page.metadata.palette_text,
                                       page.metadata.palette_text_length,
                                       "overlay") &&
        image_mapping_build_custom_palette(page.custom_mapping, "overlay")) {
        page.use_custom_palette = true;
        u32 palette_count = page.custom_mapping.custom_palette_count;
        while (palette_count >= 2u) {
            palette_count >>= 1u;
            ++page.custom_symbol_bits;
        }
    }
    return true;
}

static bool build_overlay_mask(const OverlayPage& page,
                               makocode::ByteBuffer& mask_out,
                               u64& reserved_pixels) {
    reserved_pixels = 0u;
    mask_out.release();
    u64 total_pixels = (u64)page.width * (u64)page.height;
    if (!mask_out.ensure((usize)total_pixels)) {
        return false;
    }
    mask_out.size = (usize)total_pixels;
    for (usize i = 0u; i < mask_out.size; ++i) {
        mask_out.data[i] = 0u;
    }
    if (page.data_height == 0u) {
        return true;
    }
    u32 marker_size = g_fiducial_defaults.marker_size_pixels;
    if (page.metadata.has_fiducial_size && page.metadata.fiducial_size_value > 0u && page.metadata.fiducial_size_value <= 0xFFFFFFFFull) {
        marker_size = (u32)page.metadata.fiducial_size_value;
    }
    u32 draw_height = page.height;
    if (page.data_height < page.height) {
        draw_height = page.data_height;
    }
    u32 margin = g_fiducial_defaults.margin_pixels;
    if (page.metadata.has_fiducial_margin && page.metadata.fiducial_margin_value <= 0xFFFFFFFFull) {
        margin = (u32)page.metadata.fiducial_margin_value;
    }
    double min_x = (margin < page.width) ? (double)margin : 0.0;
    double max_x = (page.width > margin)
                       ? (double)(page.width - 1u - margin)
                       : (double)(page.width - 1u);
    if (max_x < min_x) {
        max_x = min_x;
    }
    double min_y = (margin < draw_height) ? (double)margin : 0.0;
    double max_y = (draw_height > margin)
                       ? (double)(draw_height - 1u - margin)
                       : (double)(draw_height - 1u);
    if (max_y < min_y) {
        max_y = min_y;
    }
    double available_width = (max_x >= min_x) ? (max_x - min_x) : 0.0;
    double available_height = (max_y >= min_y) ? (max_y - min_y) : 0.0;
    u32 columns = (page.metadata.has_fiducial_columns && page.metadata.fiducial_columns_value > 0u)
                      ? (u32)page.metadata.fiducial_columns_value
                      : 0u;
    u32 rows = (page.metadata.has_fiducial_rows && page.metadata.fiducial_rows_value > 0u)
                   ? (u32)page.metadata.fiducial_rows_value
                   : 0u;
    if (columns == 0u || rows == 0u) {
        u32 spacing = g_fiducial_defaults.spacing_pixels;
        if (columns == 0u) {
            columns = 1u;
            if (spacing > 0u && available_width > 0.0) {
                double span = available_width / (double)spacing;
                u64 additional = (u64)span;
                columns = (u32)(additional + 1ull);
            }
        }
        if (rows == 0u) {
            rows = 1u;
            if (spacing > 0u && available_height > 0.0) {
                double span = available_height / (double)spacing;
                u64 additional = (u64)span;
                rows = (u32)(additional + 1ull);
            }
        }
    }
    for (u32 grid_row = 0u; grid_row < rows; ++grid_row) {
        double t_y = (rows == 1u) ? 0.5 : ((double)grid_row / (double)(rows - 1u));
        double center_y = min_y + (max_y - min_y) * t_y;
        int start_y = (int)(center_y - ((double)marker_size - 1.0) * 0.5);
        for (u32 grid_col = 0u; grid_col < columns; ++grid_col) {
            double t_x = (columns == 1u) ? 0.5 : ((double)grid_col / (double)(columns - 1u));
            double center_x = min_x + (max_x - min_x) * t_x;
            int start_x = (int)(center_x - ((double)marker_size - 1.0) * 0.5);
            for (u32 dy = 0u; dy < marker_size; ++dy) {
                int pixel_y = start_y + (int)dy;
                if (pixel_y < 0 || pixel_y >= (int)draw_height) {
                    continue;
                }
                bool within_data = ((u32)pixel_y < page.data_height);
                for (u32 dx = 0u; dx < marker_size; ++dx) {
                    int pixel_x = start_x + (int)dx;
                    if (pixel_x < 0 || pixel_x >= (int)page.width) {
                        continue;
                    }
                    usize index = ((usize)pixel_y * (usize)page.width) + (usize)pixel_x;
                    mask_out.data[index] = 1u;
                    if (within_data) {
                        ++reserved_pixels;
                    }
                }
            }
        }
    }

    // Protect only the written metadata barcode and codeword modules.
    if (page.metadata.has_encoded_tile &&
        page.data_height >= MetadataTile::TILE_SIDE &&
        page.width >= MetadataTile::TILE_SIDE) {
        MetadataTile::Placement placement = MetadataTile::compute_center_tile_placement(
            page.width, page.data_height);
        const MetadataTile::Values& values = page.metadata.encoded_tile;
        auto reserve_tile_module = [&](u32 tile_x, u32 tile_y) {
            u32 x = placement.x0 + tile_x;
            u32 y = placement.y0 + tile_y;
            if (!placement.valid || x >= page.width || y >= page.data_height) return;
            usize index = (usize)y * (usize)page.width + (usize)x;
            if (!mask_out.data[index]) {
                mask_out.data[index] = 1u;
                ++reserved_pixels;
            }
        };
        if (placement.valid && values.metadata_square_side > 0u &&
            values.metadata_square_side <= MetadataTile::TILE_MAX_METADATA_SQUARE_SIDE) {
            u32 tag_y = values.metadata_tag_y0;
            u32 tag_width = 32u + values.palette_count;
            for (u32 x = 0u; x < tag_width && x < MetadataTile::TILE_TAG_BITS; ++x) {
                reserve_tile_module(x, tag_y);
            }
            usize metadata_cells = (usize)values.metadata_length_prefix_bits +
                                   values.metadata_symbol_count;
            usize square_cells = (usize)values.metadata_square_side *
                                 (usize)values.metadata_square_side;
            if (metadata_cells <= square_cells) {
                for (usize cell = 0u; cell < metadata_cells; ++cell) {
                    u32 x = values.metadata_square_x0 + (u32)(cell % values.metadata_square_side);
                    u32 y = values.metadata_square_y0 + (u32)(cell / values.metadata_square_side);
                    reserve_tile_module(x, y);
                }
            }
        }
    }
    return true;
}

static bool gather_overlay_bits(const OverlayPage& page,
                                const makocode::ByteBuffer& mask,
                                makocode::ByteBuffer& bits_out,
                                u64& bit_count) {
    bit_count = 0u;
    bits_out.release();
    bool canonical_overwrite = page.metadata.has_encoded_tile &&
                             metadata_schema_is_at_least(page.metadata.encoded_tile.schema_version, 2u) &&
                             page.metadata.encoded_tile.overwrite_layout;
    u8 custom_symbol_bits = canonical_overwrite && page.use_custom_palette
                                ? page.custom_symbol_bits
                                : 0u;
    u8 sample_bits = custom_symbol_bits ? custom_symbol_bits : bits_per_sample(page.color_mode);
    u8 samples_per_pixel = custom_symbol_bits ? 1u : color_mode_samples_per_pixel(page.color_mode);
    ImageMappingConfig local_custom_mapping = page.custom_mapping;
    if (custom_symbol_bits) {
        local_custom_mapping.custom_palette_count = 1u << custom_symbol_bits;
    }
    makocode::BitWriter writer;
    for (u32 row = 0u; row < page.data_height; ++row) {
        for (u32 column = 0u; column < page.width; ++column) {
            u8 reservation_kind = 0u;
            if (mask.data && mask.size) {
                usize index = ((usize)row * (usize)page.width) + (usize)column;
                if (index < mask.size) reservation_kind = mask.data[index];
            }
            if (reservation_kind == OVERWRITE_MASK_PIXEL && !canonical_overwrite) {
                continue;
            }
            usize pixel_index = (((usize)row * (usize)page.width) + (usize)column) * 3u;
            if (custom_symbol_bits) {
                u32 symbol = 0u;
                if (!map_rgb_to_custom_symbol(local_custom_mapping,
                                              page.pixels.data + pixel_index,
                                              symbol) ||
                    !writer.write_bits(symbol, custom_symbol_bits)) {
                    return false;
                }
                continue;
            }
            u32 samples[3] = {0u, 0u, 0u};
            map_rgb_to_samples(page.color_mode, page.pixels.data + pixel_index, samples);
            for (u8 sample_idx = 0u; sample_idx < samples_per_pixel; ++sample_idx) {
                if (!writer.write_bits(samples[sample_idx], sample_bits)) {
                    return false;
                }
            }
        }
    }
    writer.align_to_byte();
    if (!custom_symbol_bits && page.color_mode == 3u) {
        usize total_bytes = writer.byte_size();
        if (total_bytes && writer.buffer.data) {
            for (usize i = 0u; i < total_bytes; ++i) {
                u8 rotate = (u8)((i % 3u) + 1u);
                writer.buffer.data[i] = rotate_right_u8(writer.buffer.data[i], rotate);
            }
        }
    }
    bit_count = writer.bit_size();
    byte_buffer_move(bits_out, writer.buffer);
    return true;
}

static bool apply_overlay_bits(const makocode::ByteBuffer& bits,
                               u64 bit_count,
                               const makocode::ByteBuffer& mask,
                               OverlayPage& page,
                               const OverlayPage* overlay_page,
                               const OverlayIgnoreColorList* ignore_list) {
    bool canonical_overwrite = page.metadata.has_encoded_tile &&
                             metadata_schema_is_at_least(page.metadata.encoded_tile.schema_version, 2u) &&
                             page.metadata.encoded_tile.overwrite_layout;
    u8 custom_symbol_bits = canonical_overwrite && page.use_custom_palette
                                ? page.custom_symbol_bits
                                : 0u;
    u8 sample_bits = custom_symbol_bits ? custom_symbol_bits : bits_per_sample(page.color_mode);
    u8 samples_per_pixel = custom_symbol_bits ? 1u : color_mode_samples_per_pixel(page.color_mode);
    const u8* bit_data = bits.data;
    usize bit_data_size = bits.size;
    makocode::ByteBuffer rotated;
    if (!custom_symbol_bits && page.color_mode == 3u && bits.size) {
        if (!rotated.ensure(bits.size)) {
            return false;
        }
        rotated.size = bits.size;
        for (usize i = 0u; i < bits.size; ++i) {
            u8 rotate = (u8)((i % 3u) + 1u);
            rotated.data[i] = rotate_left_u8(bits.data[i], rotate);
        }
        bit_data = rotated.data;
        bit_data_size = rotated.size;
    }
    ImageMappingConfig local_custom_mapping = page.custom_mapping;
    if (custom_symbol_bits) {
        local_custom_mapping.custom_palette_count = 1u << custom_symbol_bits;
    }
    const bool filter_overlay_colors = (ignore_list && overlay_page && overlay_page->pixels.data);
    u64 cursor = 0u;
    for (u32 row = 0u; row < page.data_height; ++row) {
        for (u32 column = 0u; column < page.width; ++column) {
            u8 reservation_kind = 0u;
            if (mask.data && mask.size) {
                usize index = ((usize)row * (usize)page.width) + (usize)column;
                if (index < mask.size) reservation_kind = mask.data[index];
            }
            if (reservation_kind == OVERWRITE_MASK_PIXEL && !canonical_overwrite) {
                continue;
            }

            bool skip_overlay_pixel = false;
            if (filter_overlay_colors) {
                usize overlay_index = (((usize)row * (usize)overlay_page->width) + (usize)column) * 3u;
                u8 overlay_r = overlay_page->pixels.data[overlay_index + 0u];
                u8 overlay_g = overlay_page->pixels.data[overlay_index + 1u];
                u8 overlay_b = overlay_page->pixels.data[overlay_index + 2u];
                if (overlay_color_matches_ignore(*ignore_list, overlay_r, overlay_g, overlay_b)) {
                    skip_overlay_pixel = true;
                }
            }
            u8 rgb[3];
            if (custom_symbol_bits) {
                u32 symbol = 0u;
                for (u8 bit = 0u; bit < sample_bits; ++bit) {
                    u8 bit_value = 0u;
                    if (cursor < bit_count && bit_data) {
                        usize byte_index = (usize)(cursor >> 3u);
                        if (byte_index < bit_data_size) {
                            u8 bit_mask = (u8)(1u << (cursor & 7u));
                            bit_value = (bit_data[byte_index] & bit_mask) ? 1u : 0u;
                        }
                    }
                    symbol |= ((u32)bit_value) << bit;
                    ++cursor;
                }
                const PaletteColor& color = local_custom_mapping.custom_palette[symbol];
                rgb[0] = color.r;
                rgb[1] = color.g;
                rgb[2] = color.b;
            } else {
                u32 samples[3] = {0u, 0u, 0u};
                for (u8 sample_idx = 0u; sample_idx < samples_per_pixel; ++sample_idx) {
                    u32 value = 0u;
                    for (u8 bit = 0u; bit < sample_bits; ++bit) {
                        u8 bit_value = 0u;
                        if (cursor < bit_count && bit_data) {
                            usize byte_index = (usize)(cursor >> 3u);
                            if (byte_index < bit_data_size) {
                                u8 mask_bit = (u8)(1u << (cursor & 7u));
                                bit_value = (bit_data[byte_index] & mask_bit) ? 1u : 0u;
                            }
                        }
                        value |= ((u32)bit_value) << bit;
                        ++cursor;
                    }
                    samples[sample_idx] = value;
                }
                map_samples_to_rgb(page.color_mode, samples, rgb);
            }
            usize pixel_index = (((usize)row * (usize)page.width) + (usize)column) * 3u;
            if ((pixel_index + 2u) >= page.pixels.size) {
                return false;
            }
            if (reservation_kind == OVERWRITE_MASK_PIXEL || skip_overlay_pixel) {
                continue;
            }
            page.pixels.data[pixel_index + 0u] = rgb[0];
            page.pixels.data[pixel_index + 1u] = rgb[1];
            page.pixels.data[pixel_index + 2u] = rgb[2];
        }
    }
    return true;
}

struct RawOverlayBlockTracker {
    bool enabled;
    bool limits_known;
    u64 parity_symbols;
    u64 block_total_symbols;
    u64 block_count;
    u64 block_limit_per_block;
    u64 rs_region_start;
    u64 rs_region_end;
    u64 encoded_block_bytes;
    u64 page_bit_offset;
    makocode::ByteBuffer counts;
    makocode::ByteBuffer shuffle_map;
    makocode::ByteBuffer symbol_marks;
    makocode::ByteBuffer pending_symbols;
    makocode::ByteBuffer pending_blocks;

    RawOverlayBlockTracker()
        : enabled(false),
          limits_known(false),
          parity_symbols(0u),
          block_total_symbols(0u),
          block_count(0u),
          block_limit_per_block(0u),
          rs_region_start(0u),
          rs_region_end(0u),
          encoded_block_bytes(0u),
          page_bit_offset(0u),
          counts(),
          shuffle_map(),
          symbol_marks(),
          pending_symbols(),
          pending_blocks() {}

    ~RawOverlayBlockTracker() {
        counts.release();
        shuffle_map.release();
        symbol_marks.release();
        pending_symbols.release();
        pending_blocks.release();
    }
};

struct OverlaySelector {
    bool enabled;
    u64 seed;
    u16 unknown_parity_budget;
    u16 overlay_erasure_budget;
    u16 block_total;
    u64 block_count;
    bool target_budget_active;
    u64 target_budget_remaining;
    makocode::ByteBuffer counts;
    makocode::ByteBuffer ranks;

    OverlaySelector()
        : enabled(false),
          seed(0u),
          unknown_parity_budget(0u),
          overlay_erasure_budget(0u),
          block_total(0u),
          block_count(0u),
          target_budget_active(false),
          target_budget_remaining(0u),
          counts(),
          ranks() {}
};

static void raw_overlay_tracker_init(const OverlayPage& base_page,
                                     RawOverlayBlockTracker& tracker) {
    tracker.enabled = false;
    tracker.limits_known = false;
    tracker.parity_symbols = 0u;
    tracker.block_total_symbols = 0u;
    tracker.block_count = 0u;
    tracker.block_limit_per_block = 0u;
    tracker.rs_region_start = 0u;
    tracker.rs_region_end = 0u;
    tracker.encoded_block_bytes = 0u;
    tracker.page_bit_offset = 0u;
    tracker.counts.release();
    tracker.shuffle_map.release();
    tracker.symbol_marks.release();
    tracker.pending_symbols.release();
    tracker.pending_blocks.release();
    if (!base_page.metadata.has_ecc_block_data ||
        !base_page.metadata.has_ecc_parity ||
        !base_page.metadata.has_ecc_block_count) {
        return;
    }
    u64 block_data_symbols = base_page.metadata.ecc_block_data_value;
    u64 parity_symbols = base_page.metadata.ecc_parity_value;
    u64 block_count = base_page.metadata.ecc_block_count_value;
    if (block_data_symbols == 0u || parity_symbols == 0u || block_count == 0u) {
        return;
    }
    u64 block_total_symbols = block_data_symbols + parity_symbols;
    u64 encoded_block_bytes = 0u;
    if (block_total_symbols > (U64_MAX_VALUE / block_count)) {
        return;
    }
    encoded_block_bytes = block_total_symbols * block_count;
    bool canonical_overwrite = base_page.metadata.has_encoded_tile &&
                             metadata_schema_is_at_least(base_page.metadata.encoded_tile.schema_version, 2u) &&
                             base_page.metadata.encoded_tile.overwrite_layout;
    bool headerless_layout = base_page.metadata.has_encoded_tile &&
                             metadata_schema_is_at_least(base_page.metadata.encoded_tile.schema_version, 2u) &&
                             base_page.metadata.encoded_tile.overwrite_layout;
    u64 rs_region_start = headerless_layout
                              ? 0u
                              : 8u + (u64)makocode::ECC_HEADER_TOTAL_BYTES;
    if (encoded_block_bytes > U64_MAX_VALUE - rs_region_start) {
        return;
    }
    u64 rs_region_end = rs_region_start + encoded_block_bytes;
    u64 base_bits = 0u;
    if (canonical_overwrite) {
        if (!base_page.metadata.has_page_bits || base_page.metadata.page_bits_value == 0u) {
            return;
        }
        // Canonical page_bits stores the complete encoded payload length.
        base_bits = base_page.metadata.page_bits_value;
    } else if (base_page.metadata.has_bits) {
        base_bits = base_page.metadata.bits_value;
    }
    u64 base_bytes = (base_bits + 7u) >> 3u;
    if (rs_region_start >= base_bytes) {
        return;
    }
    if (rs_region_end > base_bytes) {
        rs_region_end = base_bytes;
    }
    usize counter_bytes = 0u;
    if (block_count > (U64_MAX_VALUE / (u64)sizeof(u32))) {
        return;
    }
    counter_bytes = (usize)(block_count * (u64)sizeof(u32));
    if (!tracker.counts.ensure(counter_bytes)) {
        return;
    }
    tracker.counts.size = counter_bytes;
    for (usize i = 0u; i < counter_bytes; ++i) {
        tracker.counts.data[i] = 0u;
    }
    if (encoded_block_bytes > (U64_MAX_VALUE / (u64)sizeof(usize))) {
        return;
    }
    usize shuffle_bytes = (usize)(encoded_block_bytes * (u64)sizeof(usize));
    if (shuffle_bytes == 0u) {
        return;
    }
    if (!tracker.shuffle_map.ensure(shuffle_bytes)) {
        return;
    }
    tracker.shuffle_map.size = shuffle_bytes;
    usize* shuffle_ptr = (usize*)tracker.shuffle_map.data;
    for (u64 entry = 0u; entry < encoded_block_bytes; ++entry) {
        shuffle_ptr[entry] = (usize)entry;
    }
    makocode::Pcg64Generator rng;
    rng.seed(0u);
    for (u64 remaining = encoded_block_bytes; remaining > 1u; --remaining) {
        usize i_map = (usize)(remaining - 1u);
        u64 value = rng.next();
        usize j_map = (usize)(value % (u64)(i_map + 1u));
        usize temp = shuffle_ptr[i_map];
        shuffle_ptr[i_map] = shuffle_ptr[j_map];
        shuffle_ptr[j_map] = temp;
    }
    if (!tracker.symbol_marks.ensure((usize)encoded_block_bytes)) {
        return;
    }
    tracker.symbol_marks.size = (usize)encoded_block_bytes;
    for (u64 entry = 0u; entry < encoded_block_bytes; ++entry) {
        tracker.symbol_marks.data[entry] = 0u;
    }
    tracker.enabled = true;
    tracker.limits_known = true;
    tracker.parity_symbols = parity_symbols;
    tracker.block_total_symbols = block_total_symbols;
    tracker.block_count = block_count;
    tracker.block_limit_per_block = parity_symbols / 2u;
    if (tracker.block_limit_per_block > 1u) {
        tracker.block_limit_per_block = (tracker.block_limit_per_block * 2u) / 3u;
    }
    if (tracker.block_limit_per_block == 0u) {
        tracker.block_limit_per_block = 1u;
    }
    tracker.rs_region_start = rs_region_start;
    tracker.rs_region_end = rs_region_end;
    tracker.encoded_block_bytes = encoded_block_bytes;
}

static bool raw_overlay_tracker_try_reserve_bytes(RawOverlayBlockTracker& tracker,
                                                  u64 byte_start,
                                                  u64 byte_end) {
    if (byte_end <= tracker.rs_region_start || byte_start >= tracker.rs_region_end) {
        return true;
    }
    if (byte_start < tracker.rs_region_start) {
        byte_start = tracker.rs_region_start;
    }
    if (byte_end > tracker.rs_region_end) {
        byte_end = tracker.rs_region_end;
    }
    u32* counts = (u32*)tracker.counts.data;
    const usize* shuffle_ptr = tracker.shuffle_map.data
                                   ? (const usize*)tracker.shuffle_map.data
                                   : 0;
    u8* mark_ptr = tracker.symbol_marks.data ? tracker.symbol_marks.data : 0;
    struct RawOverlayPendingSymbol {
        u64 relative;
        usize counter_index;
        u64 block_index;
    };
    struct RawOverlayPendingBlock {
        u64 block_index;
        usize counter_index;
        u32 pending;
    };
    usize span = (usize)(byte_end - byte_start);
    if (span > (SIZE_MAX / sizeof(RawOverlayPendingSymbol))) {
        return false;
    }
    usize pending_symbol_bytes = span * sizeof(RawOverlayPendingSymbol);
    if (!tracker.pending_symbols.ensure(pending_symbol_bytes)) {
        return false;
    }
    RawOverlayPendingSymbol* pending_symbols =
        (RawOverlayPendingSymbol*)tracker.pending_symbols.data;
    usize pending_symbol_count = 0u;
    if (span > (SIZE_MAX / sizeof(RawOverlayPendingBlock))) {
        return false;
    }
    usize block_bytes = span * sizeof(RawOverlayPendingBlock);
    if (!tracker.pending_blocks.ensure(block_bytes)) {
        return false;
    }
    RawOverlayPendingBlock* block_accums =
        (RawOverlayPendingBlock*)tracker.pending_blocks.data;
    usize block_accum_count = 0u;
    for (u64 byte_index = byte_start; byte_index < byte_end; ++byte_index) {
        u64 relative = byte_index - tracker.rs_region_start;
        if (mark_ptr && mark_ptr[relative]) {
            continue;
        }
        u64 original_index = shuffle_ptr ? (u64)shuffle_ptr[(usize)relative] : relative;
        u64 block_index = original_index / tracker.block_total_symbols;
        usize counter_index = (usize)block_index;
        if (counter_index >= (tracker.counts.size / sizeof(u32))) {
            continue;
        }
        RawOverlayPendingBlock* block_entry = 0;
        for (usize i = 0u; i < block_accum_count; ++i) {
            if (block_accums[i].block_index == block_index) {
                block_entry = &block_accums[i];
                break;
            }
        }
        if (!block_entry) {
            block_entry = &block_accums[block_accum_count++];
            block_entry->block_index = block_index;
            block_entry->counter_index = counter_index;
            block_entry->pending = 0u;
        }
        u32 current_value = counts[counter_index];
        u64 prospective = (u64)current_value + (u64)block_entry->pending + 1u;
        if (prospective > tracker.block_limit_per_block) {
            return false;
        }
        RawOverlayPendingSymbol* symbol_entry = &pending_symbols[pending_symbol_count++];
        symbol_entry->relative = relative;
        symbol_entry->counter_index = counter_index;
        symbol_entry->block_index = block_index;
        block_entry->pending += 1u;
    }
    if (pending_symbol_count == 0u) {
        return true;
    }
    for (usize i = 0u; i < pending_symbol_count; ++i) {
        if (mark_ptr) {
            mark_ptr[pending_symbols[i].relative] = 1u;
        }
    }
    for (usize i = 0u; i < block_accum_count; ++i) {
        RawOverlayPendingBlock& block_entry = block_accums[i];
        u32* counter_ptr = counts + block_entry.counter_index;
        u64 new_value = (u64)(*counter_ptr) + (u64)block_entry.pending;
        if (new_value > 0xFFFFFFFFu) {
            new_value = 0xFFFFFFFFu;
        }
        *counter_ptr = (u32)new_value;
    }
    return true;
}

static bool raw_overlay_tracker_try_reserve_bits(RawOverlayBlockTracker& tracker,
                                                 u64 bit_start,
                                                 u64 bit_length) {
    if (!tracker.enabled || bit_length == 0u) {
        return true;
    }
    u64 bit_end = bit_start + bit_length;
    u64 byte_start = bit_start >> 3u;
    u64 byte_end = (bit_end + 7u) >> 3u;
    return raw_overlay_tracker_try_reserve_bytes(tracker, byte_start, byte_end);
}

static bool count_overlay_pixel_candidates(const OverlayPage& base_page,
                                          const OverlayPage& overlay_page,
                                          const makocode::ByteBuffer& base_mask,
                                          const makocode::ByteBuffer& overlay_mask,
                                          const OverlayIgnoreColorList* ignore_list,
                                          usize& out_count) {
    out_count = 0u;
    if (!base_page.pixels.data || !overlay_page.pixels.data) {
        return false;
    }
    if (base_page.width != overlay_page.width ||
        base_page.height != overlay_page.height) {
        return false;
    }
    usize total_pixels = (usize)base_page.width * (usize)base_page.height;
    if (base_page.pixels.size < total_pixels * 3u ||
        overlay_page.pixels.size < total_pixels * 3u) {
        return false;
    }
    if ((base_mask.size && base_mask.size != total_pixels) ||
        (overlay_mask.size && overlay_mask.size != total_pixels)) {
        return false;
    }
    u32 apply_height = base_page.data_height;
    const bool have_base_mask = (base_mask.data && base_mask.size);
    const bool have_overlay_mask = (overlay_mask.data && overlay_mask.size);
    bool canonical_overwrite = base_page.metadata.has_encoded_tile &&
                               metadata_schema_is_at_least(base_page.metadata.encoded_tile.schema_version, 2u) &&
                               base_page.metadata.encoded_tile.overwrite_layout;
    u64 bits_per_pixel = canonical_overwrite && base_page.use_custom_palette
                             ? (u64)base_page.custom_symbol_bits
                             : (u64)bits_per_sample(base_page.color_mode) *
                                   (u64)color_mode_samples_per_pixel(base_page.color_mode);
    u64 centered_segment_bits = 0u;
    CenteredDataRectangle payload_rectangle;
    if (canonical_overwrite) {
        u64 total_data_pixels = (u64)base_page.width * (u64)apply_height;
        if (!bits_per_pixel || total_data_pixels > U64_MAX_VALUE / bits_per_pixel) return false;
        u64 bits_per_page = total_data_pixels * bits_per_pixel;
        u64 page_index = base_page.metadata.encoded_tile.page_index;
        if (!page_index || page_index - 1u > U64_MAX_VALUE / bits_per_page) return false;
        u64 page_bit_offset = (page_index - 1u) * bits_per_page;
        if (page_bit_offset >= base_page.metadata.encoded_tile.page_bits) return false;
        centered_segment_bits = base_page.metadata.encoded_tile.page_bits - page_bit_offset;
        if (centered_segment_bits > bits_per_page) centered_segment_bits = bits_per_page;
        u64 payload_pixels = centered_segment_bits / bits_per_pixel;
        if (centered_segment_bits % bits_per_pixel) ++payload_pixels;
        if (!compute_centered_data_rectangle(base_page.width,
                                             apply_height,
                                             payload_pixels,
                                             payload_rectangle)) return false;
    }
    for (u32 row = 0u; row < (u32)apply_height; ++row) {
        for (u32 column = 0u; column < base_page.width; ++column) {
            usize pixel_index = ((usize)row * (usize)base_page.width) + (usize)column;
            bool reserved = false;
            if (have_base_mask && base_mask.data[pixel_index]) {
                reserved = true;
            }
            if (!reserved && have_overlay_mask && overlay_mask.data[pixel_index]) {
                reserved = true;
            }
            if (reserved) {
                continue;
            }
            if (canonical_overwrite) {
                if (column < payload_rectangle.x0 ||
                    column >= payload_rectangle.x0 + payload_rectangle.width ||
                    row < payload_rectangle.y0 ||
                    row >= payload_rectangle.y0 + payload_rectangle.height) {
                    continue;
                }
                u64 local_pixel = ((u64)(row - payload_rectangle.y0) *
                                   payload_rectangle.width +
                                   (u64)(column - payload_rectangle.x0));
                if (local_pixel * bits_per_pixel >= centered_segment_bits) continue;
            }
            usize byte_index = pixel_index * 3u;
            if (ignore_list) {
                u8 overlay_r = overlay_page.pixels.data[byte_index + 0u];
                u8 overlay_g = overlay_page.pixels.data[byte_index + 1u];
                u8 overlay_b = overlay_page.pixels.data[byte_index + 2u];
                if (overlay_color_matches_ignore(*ignore_list, overlay_r, overlay_g, overlay_b)) {
                    continue;
                }
            }
            out_count += 1u;
        }
    }
    return true;
}

static bool count_overlay_byte_candidates(const OverlayPage& base_page,
                                          const OverlayPage& overlay_page,
                                          const makocode::ByteBuffer& base_mask,
                                          const makocode::ByteBuffer& overlay_mask,
                                          const OverlayIgnoreColorList* ignore_list,
                                          u64& out_bytes) {
    out_bytes = 0u;
    if (!base_page.pixels.data || !overlay_page.pixels.data) {
        return false;
    }
    if (base_page.width != overlay_page.width ||
        base_page.height != overlay_page.height) {
        return false;
    }
    usize total_pixels = (usize)base_page.width * (usize)base_page.height;
    if (base_page.pixels.size < total_pixels * 3u ||
        overlay_page.pixels.size < total_pixels * 3u) {
        return false;
    }
    if ((base_mask.size && base_mask.size != total_pixels) ||
        (overlay_mask.size && overlay_mask.size != total_pixels)) {
        return false;
    }
    u32 apply_height = base_page.data_height;
    const bool have_base_mask = (base_mask.data && base_mask.size);
    const bool have_overlay_mask = (overlay_mask.data && overlay_mask.size);
    bool canonical_overwrite = base_page.metadata.has_encoded_tile &&
                             metadata_schema_is_at_least(base_page.metadata.encoded_tile.schema_version, 2u) &&
                             base_page.metadata.encoded_tile.overwrite_layout;
    u64 bits_per_pixel = canonical_overwrite && base_page.use_custom_palette
                             ? (u64)base_page.custom_symbol_bits
                             : (u64)bits_per_sample(base_page.color_mode) *
                                   (u64)color_mode_samples_per_pixel(base_page.color_mode);
    u64 bit_count = 0u;
    for (u32 row = 0u; row < (u32)apply_height; ++row) {
        for (u32 column = 0u; column < base_page.width; ++column) {
            usize pixel_index = ((usize)row * (usize)base_page.width) + (usize)column;
            bool reserved = false;
            if (have_base_mask && base_mask.data[pixel_index]) {
                reserved = true;
            }
            if (!reserved && have_overlay_mask && overlay_mask.data[pixel_index]) {
                reserved = true;
            }
            if (reserved) {
                continue;
            }
            usize byte_index = pixel_index * 3u;
            if (ignore_list) {
                u8 overlay_r = overlay_page.pixels.data[byte_index + 0u];
                u8 overlay_g = overlay_page.pixels.data[byte_index + 1u];
                u8 overlay_b = overlay_page.pixels.data[byte_index + 2u];
                if (overlay_color_matches_ignore(*ignore_list, overlay_r, overlay_g, overlay_b)) {
                    continue;
                }
            }
            bit_count += bits_per_pixel;
        }
    }
    u64 byte_count = bit_count >> 3u;
    if (bit_count & 7u) {
        ++byte_count;
    }
    out_bytes = byte_count;
    return true;
}

static bool apply_overlay_pixels_raw(const OverlayPage& overlay_page,
                                     const makocode::ByteBuffer& base_mask,
                                     const makocode::ByteBuffer& overlay_mask,
                                     u64 numerator,
                                     u64 denominator,
                                     const OverlayIgnoreColorList* ignore_list,
                                     OverlayPage& base_page,
                                     OverlaySelector* overlay_selector = 0) {
    RawOverlayBlockTracker tracker;
    raw_overlay_tracker_init(base_page, tracker);
    if (overlay_selector && overlay_selector->enabled && !tracker.enabled) {
        return false;
    }
    if (!base_page.pixels.data || !overlay_page.pixels.data) {
        return false;
    }
    if (base_page.width != overlay_page.width ||
        base_page.height != overlay_page.height) {
        return false;
    }
    usize total_pixels = (usize)base_page.width * (usize)base_page.height;
    if (base_page.pixels.size < total_pixels * 3u ||
        overlay_page.pixels.size < total_pixels * 3u) {
        return false;
    }
    if ((base_mask.size && base_mask.size != total_pixels) ||
        (overlay_mask.size && overlay_mask.size != total_pixels)) {
        return false;
    }
    u32 apply_height = base_page.data_height;
    if (apply_height == 0u) {
        return true;
    }
    const bool have_base_mask = (base_mask.data && base_mask.size);
    const bool have_overlay_mask = (overlay_mask.data && overlay_mask.size);
    bool canonical_overwrite = base_page.metadata.has_encoded_tile &&
                             metadata_schema_is_at_least(base_page.metadata.encoded_tile.schema_version, 2u) &&
                             base_page.metadata.encoded_tile.overwrite_layout;
    u64 bits_per_pixel = canonical_overwrite && base_page.use_custom_palette
                             ? (u64)base_page.custom_symbol_bits
                             : (u64)bits_per_sample(base_page.color_mode) *
                                   (u64)color_mode_samples_per_pixel(base_page.color_mode);
    struct RawOverlayPixelCandidate {
        u64 bit_start;
        usize pixel_index;
    };
    if (total_pixels > (SIZE_MAX / sizeof(RawOverlayPixelCandidate))) {
        return false;
    }
    usize candidate_capacity_bytes = total_pixels * sizeof(RawOverlayPixelCandidate);
    makocode::ByteBuffer candidate_buffer;
    if (!candidate_buffer.ensure(candidate_capacity_bytes)) {
        return false;
    }
    RawOverlayPixelCandidate* candidates =
        (RawOverlayPixelCandidate*)candidate_buffer.data;
    usize candidate_count = 0u;
    u64 stream_bit_cursor = 0u;
    u64 centered_segment_bits = 0u;
    CenteredDataRectangle payload_rectangle;
    if (canonical_overwrite) {
        u64 total_data_pixels = (u64)base_page.width * (u64)apply_height;
        if (bits_per_pixel == 0u || total_data_pixels > U64_MAX_VALUE / bits_per_pixel) {
            return false;
        }
        u64 bits_per_page = total_data_pixels * bits_per_pixel;
        u64 page_index = base_page.metadata.encoded_tile.page_index;
        if (page_index == 0u) return false;
        if (page_index - 1u > U64_MAX_VALUE / bits_per_page) return false;
        tracker.page_bit_offset = (page_index - 1u) * bits_per_page;
        if (tracker.page_bit_offset >= base_page.metadata.encoded_tile.page_bits) return false;
        centered_segment_bits = base_page.metadata.encoded_tile.page_bits -
                                tracker.page_bit_offset;
        if (centered_segment_bits > bits_per_page) centered_segment_bits = bits_per_page;
        u64 payload_pixels = centered_segment_bits / bits_per_pixel;
        if (centered_segment_bits % bits_per_pixel) ++payload_pixels;
        if (!compute_centered_data_rectangle(base_page.width,
                                             apply_height,
                                             payload_pixels,
                                             payload_rectangle)) return false;
    }
    for (u32 row = 0u; row < apply_height; ++row) {
        for (u32 column = 0u; column < base_page.width; ++column) {
            usize pixel_index = ((usize)row * (usize)base_page.width) + (usize)column;
            u8 reservation_kind = 0u;
            if (have_base_mask && base_mask.data[pixel_index] > reservation_kind) {
                reservation_kind = base_mask.data[pixel_index];
            }
            if (have_overlay_mask && overlay_mask.data[pixel_index] > reservation_kind) {
                reservation_kind = overlay_mask.data[pixel_index];
            }
            if (reservation_kind == OVERWRITE_MASK_PIXEL) {
                continue;
            }
            u64 bit_start = 0u;
            if (canonical_overwrite) {
                if (column < payload_rectangle.x0 ||
                    column >= payload_rectangle.x0 + payload_rectangle.width ||
                    row < payload_rectangle.y0 ||
                    row >= payload_rectangle.y0 + payload_rectangle.height) {
                    continue;
                }
                u64 local_pixel = ((u64)(row - payload_rectangle.y0) *
                                   payload_rectangle.width +
                                   (u64)(column - payload_rectangle.x0));
                bit_start = tracker.page_bit_offset + local_pixel * bits_per_pixel;
                if (bit_start - tracker.page_bit_offset >= centered_segment_bits) continue;
            } else {
                bit_start = stream_bit_cursor;
                stream_bit_cursor += bits_per_pixel;
            }
            usize byte_index = pixel_index * 3u;
            if (ignore_list) {
                u8 overlay_r = overlay_page.pixels.data[byte_index + 0u];
                u8 overlay_g = overlay_page.pixels.data[byte_index + 1u];
                u8 overlay_b = overlay_page.pixels.data[byte_index + 2u];
                if (overlay_color_matches_ignore(*ignore_list, overlay_r, overlay_g, overlay_b)) {
                    continue;
                }
            }
            RawOverlayPixelCandidate* entry = &candidates[candidate_count++];
            entry->pixel_index = pixel_index;
            entry->bit_start = bit_start;
        }
    }
    if (candidate_count > 1u) {
        makocode::Pcg64Generator shuffle_rng;
        shuffle_rng.seed(0u);
        for (usize remaining = candidate_count; remaining > 1u; --remaining) {
            usize i = remaining - 1u;
            u64 value = shuffle_rng.next();
            usize j = (usize)(value % (u64)remaining);
            RawOverlayPixelCandidate temp = candidates[i];
            candidates[i] = candidates[j];
            candidates[j] = temp;
        }
    }
    if (!tracker.enabled && candidate_count > 0u) {
        u64 requested = (u64)candidate_count;
        requested *= numerator;
        requested /= denominator;
        u64 cap = (u64)candidate_count / 50u; // ~2% of candidates when ECC metadata is unknown.
        if (cap == 0u) {
            cap = 1u;
        }
        if (requested > cap) {
            numerator = cap;
            denominator = (u64)candidate_count;
        }
    }
    u64 accumulator = 0u;
    for (usize idx = 0u; idx < candidate_count; ++idx) {
        const RawOverlayPixelCandidate& candidate = candidates[idx];
        if (!overlay_selector || !overlay_selector->enabled ||
            !overlay_selector->target_budget_active) {
            accumulator += numerator;
            if (accumulator < denominator) {
                continue;
            }
            accumulator -= denominator;
        }
        usize pixel_index = candidate.pixel_index;
        usize byte_index = pixel_index * 3u;
        bool changed = false;
        if (base_page.pixels.data[byte_index + 0u] != overlay_page.pixels.data[byte_index + 0u] ||
            base_page.pixels.data[byte_index + 1u] != overlay_page.pixels.data[byte_index + 1u] ||
            base_page.pixels.data[byte_index + 2u] != overlay_page.pixels.data[byte_index + 2u]) {
            changed = true;
        }
        u64 pending_blocks[8];
        u8 pending_counts[8];
        usize pending_count = 0u;
        bool selector_allowed = true;
        if (changed && overlay_selector && overlay_selector->enabled) {
            u64 bit_end = candidate.bit_start + bits_per_pixel;
            u64 byte_start = candidate.bit_start >> 3u;
            u64 byte_end = (bit_end + 7u) >> 3u;
            u64 rs_start = tracker.rs_region_start;
            u64 rs_end = tracker.rs_region_end;
            // The prefix, ECC header, and any trailing padding have no selector
            // entries. A candidate touching any of them must remain unchanged.
            if (byte_start < rs_start || byte_end > rs_end || byte_end <= byte_start) {
                selector_allowed = false;
            }
            for (u64 byte_index = byte_start; byte_index < byte_end; ++byte_index) {
                if (!selector_allowed) break;
                u64 relative = byte_index - rs_start;
                if (relative >= tracker.encoded_block_bytes ||
                    !tracker.shuffle_map.data ||
                    !overlay_selector->ranks.data) {
                    selector_allowed = false;
                    break;
                }
                u64 original_index = ((const usize*)tracker.shuffle_map.data)[(usize)relative];
                if (original_index >= overlay_selector->ranks.size) {
                    selector_allowed = false;
                    break;
                }
                u8 rank = overlay_selector->ranks.data[(usize)original_index];
                if (rank == 0u || rank > overlay_selector->overlay_erasure_budget) {
                    selector_allowed = false;
                    break;
                }
                u64 block_index = original_index / overlay_selector->block_total;
                usize pending_index = 0u;
                while (pending_index < pending_count && pending_blocks[pending_index] != block_index) {
                    ++pending_index;
                }
                if (pending_index == pending_count) {
                    if (pending_count >= sizeof(pending_blocks) / sizeof(pending_blocks[0])) {
                        selector_allowed = false;
                        break;
                    }
                    pending_blocks[pending_count] = block_index;
                    pending_counts[pending_count] = rank;
                    ++pending_count;
                } else if (rank > pending_counts[pending_index]) {
                    pending_counts[pending_index] = rank;
                }
            }
        }
        if (changed && selector_allowed && overlay_selector && overlay_selector->enabled) {
            for (usize i = 0u; i < pending_count; ++i) {
                usize block = (usize)pending_blocks[i];
                if (block >= overlay_selector->counts.size) {
                    selector_allowed = false;
                    break;
                }
            }
        }
        u64 selector_budget_cost = 0u;
        if (changed && selector_allowed && overlay_selector && overlay_selector->enabled &&
            overlay_selector->target_budget_active) {
            for (usize i = 0u; i < pending_count; ++i) {
                usize block = (usize)pending_blocks[i];
                u64 current = overlay_selector->counts.data[block];
                if ((u64)pending_counts[i] > current) {
                    u64 increase = (u64)pending_counts[i] - current;
                    if (increase > U64_MAX_VALUE - selector_budget_cost) {
                        selector_allowed = false;
                        break;
                    }
                    selector_budget_cost += increase;
                }
            }
            if (selector_budget_cost > overlay_selector->target_budget_remaining) {
                selector_allowed = false;
            }
        }
        if (!selector_allowed) {
            continue;
        }
        if (changed && overlay_selector && overlay_selector->enabled) {
            for (usize i = 0u; i < pending_count; ++i) {
                usize block = (usize)pending_blocks[i];
                if (pending_counts[i] > overlay_selector->counts.data[block]) {
                    overlay_selector->counts.data[block] = pending_counts[i];
                }
            }
            if (overlay_selector->target_budget_active) {
                overlay_selector->target_budget_remaining -= selector_budget_cost;
            }
        } else if (changed) {
            if (!raw_overlay_tracker_try_reserve_bits(tracker, candidate.bit_start, bits_per_pixel)) {
                continue;
            }
        }
        memcpy(base_page.pixels.data + byte_index,
               overlay_page.pixels.data + byte_index,
               3u);
    }
    return true;
}

static bool serialize_overlay_page(const OverlayPage& page,
                                   makocode::ByteBuffer& output) {
    output.release();
    if (!ppm_write_metadata_header(page.metadata, output)) {
        return false;
    }
    if (!ppm_write_dimensions((u64)page.width, (u64)page.height, output)) {
        return false;
    }
    usize total_bytes = (usize)page.width * (usize)page.height * 3u;
    return output.append_bytes(page.pixels.data, total_bytes);
}

static bool write_buffer_to_fd(int fd, const makocode::ByteBuffer& buffer) {
    usize offset = 0u;
    while (offset < buffer.size) {
        unsigned long chunk = (unsigned long)(buffer.size - offset);
        if (chunk > 65536ul) {
            chunk = 65536ul;
        }
        int wrote = write(fd, buffer.data + offset, chunk);
        if (wrote <= 0) {
            return false;
        }
        offset += (usize)wrote;
    }
    return true;
}

static int command_overlay(int arg_count, char** args) {
    if (arguments_request_help(arg_count, args)) {
        write_overlay_help();
        return 0;
    }
    OverlayIgnoreColorList ignore_colors;
    ignore_colors.count = 0u;
    const char* ignore_text = 0;
    usize ignore_length = 0u;
    bool ignore_specified = false;
    bool ecc_target_specified = false;
    bool debug_requested = false;
    u64 ecc_target_numerator = 0u;
    u64 ecc_target_denominator = 1u;
    int option_index = 0;
    const char ignore_option[] = "--ignore-colors";
    const char ignore_prefix[] = "--ignore-colors=";
    const char ecc_target_option[] = "--overlay-ecc-target";
    const char ecc_target_prefix[] = "--overlay-ecc-target=";
    const char debug_option[] = "--debug";
    while (option_index < arg_count) {
        const char* arg = args[option_index];
        
        usize length = ascii_length(arg);
        if (ascii_equals_token(arg, length, debug_option)) {
            if (debug_requested) {
                console_line(2, "overlay: --debug specified multiple times");
                return 1;
            }
            debug_requested = true;
            ++option_index;
            continue;
        }
        if (ascii_equals_token(arg, length, ignore_option)) {
            if (ignore_specified) {
                console_line(2, "overlay: --ignore-colors specified multiple times");
                return 1;
            }
            if ((option_index + 1) >= arg_count) {
                console_line(2, "overlay: --ignore-colors requires a value");
                return 1;
            }
            const char* value = args[option_index + 1];
            usize value_length = ascii_length(value);
            if (value_length == 0u) {
                console_line(2, "overlay: --ignore-colors requires a non-empty value");
                return 1;
            }
            ignore_text = value;
            ignore_length = value_length;
            ignore_specified = true;
            option_index += 2;
            continue;
        }
        if (ascii_starts_with(arg, ignore_prefix)) {
            if (ignore_specified) {
                console_line(2, "overlay: --ignore-colors specified multiple times");
                return 1;
            }
            const char* value = arg + (sizeof(ignore_prefix) - 1u);
            if (*value == '\0') {
                console_line(2, "overlay: --ignore-colors requires a non-empty value");
                return 1;
            }
            ignore_text = value;
            ignore_length = ascii_length(value);
            ignore_specified = true;
            ++option_index;
            continue;
        }
        if (ascii_equals_token(arg, length, ecc_target_option)) {
            if (ecc_target_specified) {
                console_line(2, "overlay: --overlay-ecc-target specified multiple times");
                return 1;
            }
            const char* value = args[option_index + 1];
            if (!value) {
                console_line(2, "overlay: --overlay-ecc-target requires a value");
                return 1;
            }
            usize value_length = ascii_length(value);
            if (value_length == 0u) {
                console_line(2, "overlay: --overlay-ecc-target requires a non-empty value");
                return 1;
            }
            if (!ascii_to_fraction(value, value_length, ecc_target_numerator, ecc_target_denominator)) {
                console_line(2, "overlay: --overlay-ecc-target requires a decimal value such as 0.5");
                return 1;
            }
            ecc_target_specified = true;
            option_index += 2;
            continue;
        }
        if (ascii_starts_with(arg, ecc_target_prefix)) {
            if (ecc_target_specified) {
                console_line(2, "overlay: --overlay-ecc-target specified multiple times");
                return 1;
            }
            const char* value = arg + (sizeof(ecc_target_prefix) - 1u);
            if (*value == '\0') {
                console_line(2, "overlay: --overlay-ecc-target requires a non-empty value");
                return 1;
            }
            if (!ascii_to_fraction(value, ascii_length(value), ecc_target_numerator, ecc_target_denominator)) {
                console_line(2, "overlay: --overlay-ecc-target requires a decimal value such as 0.5");
                return 1;
            }
            ecc_target_specified = true;
            ++option_index;
            continue;
        }
        break;
    }
    int positional_count = arg_count - option_index;
    if (positional_count != 3) {
        console_line(2, "overlay: usage: makocode overlay [--debug] [--ignore-colors COLORS] [--overlay-ecc-target TARGET] BASE.ppm OVERLAY.ppm FRACTION");
        return 1;
    }
    const char* base_path = args[option_index];
    const char* overlay_path = args[option_index + 1];
    const char* fraction_text = args[option_index + 2];
    if (ignore_specified) {
        if (!parse_overlay_ignore_colors(ignore_text, ignore_length, ignore_colors)) {
            return 1;
        }
    }
    const OverlayIgnoreColorList* overlay_ignore = (ignore_colors.count > 0u) ? &ignore_colors : 0;
    usize fraction_length = ascii_length(fraction_text);
    u64 numerator = 0u;
    u64 denominator = 1u;
    if (fraction_length == 0u ||
        !ascii_to_fraction(fraction_text, fraction_length, numerator, denominator)) {
        console_line(2, "overlay: fraction must be a decimal value such as 0.25");
        return 1;
    }
    if (numerator > denominator) {
        numerator = denominator;
    }
    OverlayPage base_page;
    OverlayPage overlay_page;
    if (!load_overlay_page(base_path, base_page)) {
        return 1;
    }
    if (!load_overlay_page(overlay_path, overlay_page)) {
        return 1;
    }
    if (base_page.width != overlay_page.width ||
        base_page.height != overlay_page.height) {
        console_line(2, "overlay: ppm images must have identical dimensions");
        return 1;
    }
    // Align overlay layout to the base so fiducial/data regions match pixel-for-pixel.
    overlay_apply_base_layout(base_page, overlay_page);
    bool same_symbol_mapping = (base_page.color_mode == overlay_page.color_mode);
    if (base_page.use_custom_palette || overlay_page.use_custom_palette) {
        same_symbol_mapping = base_page.use_custom_palette && overlay_page.use_custom_palette &&
                              base_page.metadata.has_encoded_tile &&
                              metadata_schema_is_at_least(base_page.metadata.encoded_tile.schema_version, 2u) &&
                              base_page.metadata.encoded_tile.overwrite_layout &&
                              base_page.custom_mapping.custom_palette_count ==
                                  overlay_page.custom_mapping.custom_palette_count;
        if (same_symbol_mapping) {
            for (u32 i = 0u; i < base_page.custom_mapping.custom_palette_count; ++i) {
                if (!palette_colors_equal(base_page.custom_mapping.custom_palette[i],
                                          overlay_page.custom_mapping.custom_palette[i])) {
                    same_symbol_mapping = false;
                    break;
                }
            }
        }
    }
    makocode::ByteBuffer base_mask;
    makocode::ByteBuffer overlay_mask;
    u64 base_reserved = 0u;
    u64 overlay_reserved = 0u;
    if (!build_overlay_mask(base_page, base_mask, base_reserved)) {
        console_line(2, "overlay: failed to prepare fiducial mask for base image");
        return 1;
    }
    if (!build_overlay_mask(overlay_page, overlay_mask, overlay_reserved)) {
        console_line(2, "overlay: failed to prepare fiducial mask for overlay image");
        return 1;
    }
    OverlaySelector overlay_selector;
    bool canonical_overlay = base_page.metadata.has_encoded_tile &&
                           metadata_schema_is_at_least(base_page.metadata.encoded_tile.schema_version, 2u) &&
                           base_page.metadata.encoded_tile.overwrite_layout;
    if (canonical_overlay) {
        const MetadataTile::Values& tile = base_page.metadata.encoded_tile;
        if (!tile.overlay_selector_present) {
            console_line(2, "overlay: page was encoded without an overlay parity reserve");
            return 1;
        }
        if (!tile.ecc_enabled || tile.ecc_block_count == 0u || tile.ecc_parity == 0u ||
            tile.ecc_block_data == 0u ||
            (u64)tile.ecc_block_data + tile.ecc_parity > 255u ||
            tile.ecc_parity > 255u) {
            console_line(2, "overlay: canonical page has invalid ECC metadata");
            return 1;
        }
        overlay_selector.seed = tile.overlay_selector_seed;
        overlay_selector.unknown_parity_budget = tile.unknown_parity_budget;
        overlay_selector.overlay_erasure_budget = tile.overlay_erasure_budget;
        overlay_selector.block_total = (u16)(tile.ecc_block_data + tile.ecc_parity);
        overlay_selector.block_count = tile.ecc_block_count;
        if ((u32)overlay_selector.unknown_parity_budget +
                    (u32)overlay_selector.overlay_erasure_budget > tile.ecc_parity ||
            overlay_selector.block_count > (u64)USIZE_MAX_VALUE ||
            !overlay_selector.counts.ensure((usize)overlay_selector.block_count) ||
            overlay_selector.block_count > (u64)USIZE_MAX_VALUE / overlay_selector.block_total ||
            !overlay_selector.ranks.ensure((usize)(overlay_selector.block_count *
                                                   overlay_selector.block_total))) {
            console_line(2, "overlay: canonical selector map is too large");
            return 1;
        }
        overlay_selector.counts.size = (usize)overlay_selector.block_count;
        for (usize block = 0u; block < overlay_selector.counts.size; ++block) {
            overlay_selector.counts.data[block] = 0u;
        }
        overlay_selector.ranks.size = (usize)(overlay_selector.block_count *
                                              overlay_selector.block_total);
        u8 selector_mask[255];
        u8 selector_ranks[255];
        for (u32 block = 0u; block < overlay_selector.block_count; ++block) {
            if (!makocode::overlay_selector_mask(overlay_selector.seed,
                                                         block,
                                                         overlay_selector.block_total,
                                                         (u8)overlay_selector.overlay_erasure_budget,
                                                         selector_mask,
                                                         selector_ranks)) {
                console_line(2, "overlay: failed to generate canonical selector map");
                return 1;
            }
            usize offset = (usize)block * (usize)overlay_selector.block_total;
            memcpy(overlay_selector.ranks.data + offset,
                   selector_ranks,
                   overlay_selector.block_total);
        }
        overlay_selector.enabled = true;
    }
    if (ecc_target_specified) {
        RawOverlayBlockTracker ecc_tracker;
        raw_overlay_tracker_init(base_page, ecc_tracker);
        if (!ecc_tracker.enabled) {
            console_line(2, "overlay: --overlay-ecc-target requires ECC metadata");
            return 1;
        }
        u64 candidate_limit = 0u;
        if (!same_symbol_mapping || overlay_selector.enabled) {
            usize candidate_count = 0u;
            count_overlay_pixel_candidates(base_page,
                                           overlay_page,
                                           base_mask,
                                           overlay_mask,
                                           overlay_ignore,
                                           candidate_count);
            candidate_limit = (candidate_count > (usize)U64_MAX_VALUE)
                                ? U64_MAX_VALUE
                                : (u64)candidate_count;
        } else {
            u64 candidate_bytes = 0u;
            if (!count_overlay_byte_candidates(base_page,
                                               overlay_page,
                                               base_mask,
                                               overlay_mask,
                                               overlay_ignore,
                                               candidate_bytes)) {
                console_line(2, "overlay: failed to evaluate overlay candidates");
                return 1;
            }
            candidate_limit = candidate_bytes;
        }
        long double target_fraction = (long double)ecc_target_numerator /
                                       (long double)ecc_target_denominator;
        if (target_fraction > 1.0L) {
            target_fraction = 1.0L;
        }
        u64 total_limit = ecc_tracker.block_count * ecc_tracker.block_limit_per_block;
        if (overlay_selector.enabled) {
            total_limit = 0u;
            for (usize block = 0u; block < overlay_selector.counts.size; ++block) {
                u64 current = overlay_selector.counts.data[block];
                if (current < overlay_selector.overlay_erasure_budget) {
                    u64 available = (u64)overlay_selector.overlay_erasure_budget - current;
                    if (available > U64_MAX_VALUE - total_limit) {
                        total_limit = U64_MAX_VALUE;
                        break;
                    }
                    total_limit += available;
                }
            }
        }
        long double desired_changes = target_fraction * (long double)total_limit;
        u64 target_changes = (u64)(desired_changes + 0.5L);
        if (target_changes == 0u && target_fraction > 0.0L && candidate_limit > 0u) {
            target_changes = 1u;
        }
        if (candidate_limit == 0u) {
            numerator = 0u;
        } else if (overlay_selector.enabled) {
            overlay_selector.target_budget_active = true;
            overlay_selector.target_budget_remaining = target_changes;
            numerator = 1u;
            denominator = 1u;
        } else {
            if (target_changes > candidate_limit) {
                target_changes = candidate_limit;
            }
            numerator = target_changes;
            denominator = candidate_limit;
        }
    }
    if (numerator == 0u) {
        if (!write_buffer_to_fd(1, base_page.original)) {
            console_line(2, "overlay: failed to write original base image");
            return 1;
        }
        return 0;
    }
    if (!same_symbol_mapping || overlay_selector.enabled) {
        if (!apply_overlay_pixels_raw(overlay_page,
                                      base_mask,
                                      overlay_mask,
                                      numerator,
                                      denominator,
                                      overlay_ignore,
                                      base_page,
                                      &overlay_selector)) {
            console_line(2, "overlay: failed to copy raw pixel data between color modes");
            return 1;
        }
    } else {
        makocode::ByteBuffer base_bits;
        makocode::ByteBuffer overlay_bits;
        u64 base_bit_count = 0u;
        u64 overlay_bit_count = 0u;
        if (!gather_overlay_bits(base_page, base_mask, base_bits, base_bit_count)) {
            console_line(2, "overlay: failed to extract data bytes from base image");
            return 1;
        }
        if (!gather_overlay_bits(overlay_page, overlay_mask, overlay_bits, overlay_bit_count)) {
            console_line(2, "overlay: failed to extract data bytes from overlay image");
            return 1;
        }
        if (base_bit_count == 0u || base_bits.size == 0u) {
            console_line(2, "overlay: base image does not contain data bytes to modify");
            return 1;
        }
        if (overlay_bits.size == 0u) {
            console_line(2, "overlay: overlay image does not provide data bytes");
            return 1;
        }
        u64 base_bytes = (base_bit_count + 7u) >> 3u;
        u64 overlay_bytes = (overlay_bit_count + 7u) >> 3u;
        u64 copy_bytes = (base_bytes < overlay_bytes) ? base_bytes : overlay_bytes;
        if (copy_bytes == 0u) {
            console_line(2, "overlay: no whole bytes available for overlay");
            return 1;
        }
        u8* base_ptr = base_bits.data;
        const u8* overlay_ptr = overlay_bits.data;
        if (!base_ptr || !overlay_ptr) {
            console_line(2, "overlay: internal byte buffer unavailable");
            return 1;
        }
        u64 accumulator = 0u;
        makocode::ByteBuffer block_counters;
        makocode::ByteBuffer block_shuffle_map;
        u16* block_counters_ptr = 0;
        usize* block_shuffle_map_ptr = 0;
        bool block_limit_active = false;
        u64 block_limit_start = 0u;
        u64 block_limit_end = 0u;
        u64 block_total_symbols = 0u;
        u64 block_total_count = 0u;
        u64 block_limit_per_block = 0u;
        u64 shuffle_entry_count = 0u;
        bool headerless_layout = base_page.metadata.has_encoded_tile &&
                                 metadata_schema_is_at_least(base_page.metadata.encoded_tile.schema_version, 2u) &&
                                 base_page.metadata.encoded_tile.overwrite_layout;
        u64 rs_region_start = headerless_layout
                                  ? 0u
                                  : 8u + (u64)makocode::ECC_HEADER_TOTAL_BYTES;
        u64 block_data = 0u;
        u64 parity = 0u;
        u64 block_count_value = 0u;
        if (headerless_layout) {
            const MetadataTile::Values& tile = base_page.metadata.encoded_tile;
            if (tile.ecc_enabled) {
                block_data = tile.ecc_block_data;
                parity = tile.ecc_parity;
                block_count_value = tile.ecc_block_count;
            }
        } else if (base_bytes >= rs_region_start) {
            usize payload_byte_count = (base_bytes - 8u > (u64)USIZE_MAX_VALUE)
                                           ? USIZE_MAX_VALUE
                                           : (usize)(base_bytes - 8u);
            if (payload_byte_count >= makocode::ECC_HEADER_TOTAL_BYTES) {
                makocode::EccHeaderInfo ecc_header;
                if (makocode::parse_ecc_header(base_ptr + 8u,
                                               payload_byte_count,
                                               ecc_header) &&
                    ecc_header.valid && ecc_header.enabled) {
                    block_data = (u64)ecc_header.block_data;
                    parity = (u64)ecc_header.parity;
                    block_count_value = ecc_header.block_count;
                }
            }
        }
        u64 block_total = block_data + parity;
        if (block_data && parity && block_total && block_count_value &&
            block_total <= (U64_MAX_VALUE / block_count_value)) {
            u64 encoded_block_bytes = block_total * block_count_value;
            u64 available_rs_bytes = base_bytes - rs_region_start;
            if (encoded_block_bytes > available_rs_bytes) {
                encoded_block_bytes = available_rs_bytes;
            }
            if (encoded_block_bytes > 0u &&
                block_count_value <= (u64)(USIZE_MAX_VALUE / sizeof(u16))) {
                usize counter_bytes = (usize)(block_count_value * (u64)sizeof(u16));
                if (counter_bytes != 0u && block_counters.ensure(counter_bytes)) {
                    block_counters.size = counter_bytes;
                    for (usize counter_index = 0u; counter_index < counter_bytes; ++counter_index) {
                        block_counters.data[counter_index] = 0u;
                    }
                    block_total_symbols = block_total;
                    block_total_count = block_count_value;
                    // RS can correct up to t = floor(parity/2) symbol errors per block.
                    // Stay slightly under that theoretical maximum to leave room for scan damage.
                    block_limit_per_block = parity / 2u;
                    if (block_limit_per_block > 1u) {
                        block_limit_per_block -= 1u;
                    } else {
                        block_limit_per_block = 1u;
                    }
                    if (encoded_block_bytes <= (u64)USIZE_MAX_VALUE) {
                        usize entries = (usize)encoded_block_bytes;
                        if (entries != 0u &&
                            entries <= (USIZE_MAX_VALUE / sizeof(usize))) {
                            usize map_bytes = entries * sizeof(usize);
                            if (map_bytes != 0u && block_shuffle_map.ensure(map_bytes)) {
                                block_shuffle_map.size = map_bytes;
                                block_shuffle_map_ptr = (usize*)block_shuffle_map.data;
                                for (usize map_index = 0u; map_index < entries; ++map_index) {
                                    block_shuffle_map_ptr[map_index] = map_index;
                                }
                                makocode::Pcg64Generator rng;
                                rng.seed(0u);
                                for (usize map_index = entries; map_index > 1u; --map_index) {
                                    usize i_map = map_index - 1u;
                                    u64 value = rng.next();
                                    usize j_map = (usize)(value % (u64)(i_map + 1u));
                                    usize temp = block_shuffle_map_ptr[i_map];
                                    block_shuffle_map_ptr[i_map] = block_shuffle_map_ptr[j_map];
                                    block_shuffle_map_ptr[j_map] = temp;
                                }
                                block_counters_ptr = (u16*)block_counters.data;
                                shuffle_entry_count = (u64)entries;
                                block_limit_start = rs_region_start;
                                block_limit_end = block_limit_start + shuffle_entry_count;
                                block_limit_active = true;
                            }
                        }
                    }
                }
            }
        }

        // If ECC metadata is available and the caller did not specify an explicit ECC target,
        // clamp the requested overlay fraction to a conservative bound based on correctable
        // symbols. The raw fraction argument is in terms of bytes to replace and can easily
        // exceed ECC capabilities when used with heavy overlays.
        if (!ecc_target_specified &&
            block_limit_active &&
            block_total_symbols > 0u &&
            block_total_count > 0u &&
            block_limit_per_block > 0u &&
            copy_bytes > 0u &&
            denominator > 0u) {
            // Keep generous headroom beyond the theoretical RS limit to survive
            // additional damage (e.g., scanning noise) on top of the overlay.
            u64 safe_per_block = block_limit_per_block;
            if (safe_per_block > 1u) {
                safe_per_block = (safe_per_block * 2u) / 3u; // ~67% of the nominal limit
            }
            __uint128_t safe_total = (__uint128_t)safe_per_block * (__uint128_t)block_total_count;
            __uint128_t max_num128 = safe_total * (__uint128_t)denominator;
            max_num128 /= (__uint128_t)copy_bytes;
            u64 max_numerator = (max_num128 > (__uint128_t)U64_MAX_VALUE) ? U64_MAX_VALUE : (u64)max_num128;
            if (max_numerator == 0u && safe_total > 0u) {
                max_numerator = 1u;
            }
            if (numerator > max_numerator) {
                numerator = max_numerator;
            }
        }
        for (u64 i = 0u; i < copy_bytes; ++i) {
            accumulator += numerator;
            if (accumulator < denominator) {
                continue;
            }
            bool replaced = false;
            bool skipped_for_limit = false;
            if (block_limit_active &&
                block_shuffle_map_ptr &&
                block_counters_ptr &&
                block_total_symbols > 0u &&
                block_total_count > 0u &&
                i >= block_limit_start &&
                i < block_limit_end) {
                u64 relative = i - block_limit_start;
                if (relative < shuffle_entry_count) {
                    u64 original_index = (u64)block_shuffle_map_ptr[(usize)relative];
                    u64 block_index = original_index / block_total_symbols;
                    if (overlay_selector.enabled) {
                        if (original_index >= overlay_selector.ranks.size ||
                            block_index >= overlay_selector.counts.size) {
                            skipped_for_limit = true;
                        } else {
                            u8 selector_rank = overlay_selector.ranks.data[(usize)original_index];
                            if (selector_rank == 0u ||
                                selector_rank > overlay_selector.overlay_erasure_budget) {
                                skipped_for_limit = true;
                            } else {
                                if (base_ptr[i] != overlay_ptr[i] &&
                                    selector_rank > overlay_selector.counts.data[(usize)block_index]) {
                                    overlay_selector.counts.data[(usize)block_index] = selector_rank;
                                }
                                base_ptr[i] = overlay_ptr[i];
                                replaced = true;
                            }
                        }
                    } else if (block_index < block_total_count) {
                        usize counter_index = (usize)block_index;
                        u16 current_count = block_counters_ptr[counter_index];
                        if ((u64)current_count < block_limit_per_block) {
                            base_ptr[i] = overlay_ptr[i];
                            block_counters_ptr[counter_index] = (u16)(current_count + 1u);
                            replaced = true;
                        } else {
                            skipped_for_limit = true;
                        }
                    }
                }
            }
            if (!replaced && !skipped_for_limit) {
                base_ptr[i] = overlay_ptr[i];
                replaced = true;
            }
            if (replaced) {
                accumulator -= denominator;
            }
        }
        
        if (!apply_overlay_bits(base_bits, base_bit_count, base_mask, base_page, &overlay_page, overlay_ignore)) {
            console_line(2, "overlay: failed to map merged bytes back to base image");
            return 1;
        }
    }
    if (debug_requested && overlay_selector.enabled) {
        u64 used = 0u;
        for (usize block = 0u; block < overlay_selector.counts.size; ++block) {
            if (overlay_selector.counts.data[block] > U64_MAX_VALUE - used) {
                console_line(2, "overlay: selector accounting overflow");
                return 1;
            }
            used += overlay_selector.counts.data[block];
        }
        if (overlay_selector.block_count &&
            overlay_selector.overlay_erasure_budget >
                U64_MAX_VALUE / overlay_selector.block_count) {
            console_line(2, "overlay: selector capacity overflow");
            return 1;
        }
        u64 capacity = overlay_selector.block_count * overlay_selector.overlay_erasure_budget;
        console_write(2, "overlay selector symbols used: ");
        char number[32];
        u64_to_ascii(used, number, sizeof(number));
        console_write(2, number);
        console_write(2, "/");
        u64_to_ascii(capacity, number, sizeof(number));
        console_line(2, number);
    }
    makocode::ByteBuffer output;
    if (!serialize_overlay_page(base_page, output)) {
        console_line(2, "overlay: failed to serialize merged ppm");
        return 1;
    }
    if (!write_buffer_to_fd(1, output)) {
        console_line(2, "overlay: failed to emit merged ppm");
        return 1;
    }
    return 0;
}

static int command_decode(int arg_count, char** args) {
    if (arguments_request_help(arg_count, args)) {
        write_decode_help();
        return 0;
    }
    ImageMappingConfig mapping;
    static const usize MAX_INPUT_FILES = 256u;
    const char* input_files[MAX_INPUT_FILES];
    usize file_count = 0u;
    MetadataTile::Values encoded_pages[MAX_INPUT_FILES];
    bool encoded_page_present[MAX_INPUT_FILES] = {};
    usize encoded_page_count = 0u;
    bool decoded_file_requested = false;
    bool decoded_stdout_requested = false;
    u64 encoded_frame_bits = 0u;
    makocode::ByteBuffer password_buffer;
    bool have_password = false;
    makocode::ByteBuffer output_dir_buffer;
    const char* output_dir = ".";
    bool have_output_dir = false;
    bool debug_requested = false;
    for (int i = 0; i < arg_count; ++i) {
        bool handled = false;
        if (!process_image_mapping_option(arg_count, args, &i, mapping, "decode", &handled)) {
            return 1;
        }
        if (handled) {
            continue;
        }
        const char* arg = args[i];
        if (ascii_equals_token(arg, ascii_length(arg), "--decoded-file")) {
            decoded_file_requested = true;
            continue;
        }
        if (ascii_equals_token(arg, ascii_length(arg), "--decoded-stdout")) {
            decoded_stdout_requested = true;
            continue;
        }
        if (ascii_equals_token(arg, ascii_length(arg), "--debug")) {
            debug_requested = true;
            continue;
        }
        
        const char output_prefix[] = "--output-dir=";
        const char* output_value = 0;
        usize output_length = 0u;
        if (ascii_equals_token(arg, ascii_length(arg), "--output-dir")) {
            if (have_output_dir) {
                console_line(2, "decode: output directory specified multiple times");
                return 1;
            }
            if ((i + 1) >= arg_count) {
                console_line(2, "decode: --output-dir requires a non-empty path");
                return 1;
            }
            output_value = args[i + 1];
            output_length = ascii_length(output_value);
            i += 1;
        } else if (ascii_starts_with(arg, output_prefix)) {
            if (have_output_dir) {
                console_line(2, "decode: output directory specified multiple times");
                return 1;
            }
            output_value = arg + (sizeof(output_prefix) - 1u);
            output_length = ascii_length(output_value);
        }
        if (output_value) {
            if (output_length == 0u) {
                console_line(2, "decode: --output-dir requires a non-empty path");
                return 1;
            }
    if (!output_dir_buffer.ensure(output_length + 1u)) {
        console_line(2, "decode: failed to allocate output directory buffer");
        return 1;
    }
            for (usize j = 0u; j < output_length; ++j) {
                output_dir_buffer.data[j] = (u8)output_value[j];
            }
            output_dir_buffer.data[output_length] = 0u;
            output_dir_buffer.size = output_length;
            output_dir = (const char*)output_dir_buffer.data;
            have_output_dir = true;
            continue;
        }
        const char password_prefix[] = "--password=";
        const char* password_value = 0;
        usize password_length = 0u;
        if (ascii_equals_token(arg, ascii_length(arg), "--password")) {
            if (have_password) {
                console_line(2, "decode: password specified multiple times");
                return 1;
            }
            if ((i + 1) >= arg_count) {
                console_line(2, "decode: --password requires a non-empty value");
                return 1;
            }
            password_value = args[i + 1];
            password_length = ascii_length(password_value);
            i += 1;
        } else if (ascii_starts_with(arg, password_prefix)) {
            if (have_password) {
                console_line(2, "decode: password specified multiple times");
                return 1;
            }
            password_value = arg + (sizeof(password_prefix) - 1u);
            password_length = ascii_length(password_value);
        }
        if (password_value) {
            if (password_length == 0u) {
                console_line(2, "decode: --password requires a non-empty value");
                return 1;
            }
            if (!password_buffer.ensure(password_length)) {
                console_line(2, "decode: failed to allocate password buffer");
                return 1;
            }
            for (usize j = 0u; j < password_length; ++j) {
                password_buffer.data[j] = (u8)password_value[j];
            }
            password_buffer.size = password_length;
            have_password = true;
            continue;
        }
        if (file_count >= MAX_INPUT_FILES) {
            console_line(2, "decode: too many input files");
            return 1;
        }
    input_files[file_count++] = arg;
}
    if (decoded_stdout_requested && (decoded_file_requested || debug_requested)) {
        console_line(2, "decode: --decoded-stdout cannot be combined with --decoded-file or --debug");
        return 1;
    }
    if (mapping.palette_set) {
        if (!image_mapping_build_custom_palette(mapping, "decode")) {
            return 1;
        }
    }
    makocode::ByteBuffer bitstream;
    makocode::ByteBuffer erased_payload_symbols;
    makocode::ByteBuffer overlay_selector_counts;
    u64 overlay_selector_seed = 0u;
    u16 overlay_unknown_parity_budget = 0u;
    u16 overlay_erasure_budget = 0u;
    u64 bit_count = 0u;
    makocode::ByteBuffer frame_bits_for_length_recovery;
    u64 frame_bit_count_for_length_recovery = 0u;
    PpmParserState aggregate_state;
    MetadataTile::Values single_retry_tile;
    bool single_retry_tile_available = false;
    bool have_metadata = false;
    bool force_disable_subgrid = false;
    bool retried_subgrid = false;
    bool force_tile_center_sampling = false;
    u32 small_scan_geometry_variant = 0u;
    makocode::ByteBuffer debug_fiducial_csv;
    makocode::ByteBuffer debug_fiducial_path;
    const usize debug_fiducial_header_size = (usize)sizeof("page,row,column,x,y,logical_x,logical_y\n") - 1u;
    makocode::ByteBuffer debug_affine_csv;
    makocode::ByteBuffer debug_affine_path;
    const usize debug_affine_header_size = (usize)sizeof("page,has_affine,scale,rotation_degrees,a00,a01,a10,a11,tx,ty\n") - 1u;
    if (debug_requested) {
        if (!debug_fiducial_csv.append_ascii("page,row,column,x,y,logical_x,logical_y\n") ||
            !join_output_path(output_dir, "decode_fiducials.csv", debug_fiducial_path) ||
            !ensure_parent_directories((const char*)debug_fiducial_path.data) ||
            !write_bytes_to_file((const char*)debug_fiducial_path.data,
                                 debug_fiducial_csv.data,
                                 debug_fiducial_csv.size) ||
            !debug_affine_csv.append_ascii("page,has_affine,scale,rotation_degrees,a00,a01,a10,a11,tx,ty\n") ||
            !join_output_path(output_dir, "decode_affine.csv", debug_affine_path) ||
            !ensure_parent_directories((const char*)debug_affine_path.data) ||
            !write_bytes_to_file((const char*)debug_affine_path.data,
                                 debug_affine_csv.data,
                                 debug_affine_csv.size)) {
            console_line(2, "decode: failed to prepare fiducial CSV");
            return 1;
        }
    }
retry_decode:
    encoded_page_count = 0u;
    encoded_frame_bits = 0u;
    frame_bits_for_length_recovery.release();
    frame_bit_count_for_length_recovery = 0u;
    erased_payload_symbols.release();
    overlay_selector_counts.release();
    overlay_selector_seed = 0u;
    overlay_unknown_parity_budget = 0u;
    overlay_erasure_budget = 0u;
    if (debug_requested && debug_fiducial_csv.size > debug_fiducial_header_size) {
        debug_fiducial_csv.size = debug_fiducial_header_size;
        if (!write_bytes_to_file((const char*)debug_fiducial_path.data,
                                 debug_fiducial_csv.data,
                                 debug_fiducial_csv.size)) {
            console_line(2, "decode: failed to reset fiducial CSV");
            return 1;
        }
    }
    if (debug_requested && debug_affine_csv.size > debug_affine_header_size) {
        debug_affine_csv.size = debug_affine_header_size;
        if (!write_bytes_to_file((const char*)debug_affine_path.data,
                                 debug_affine_csv.data,
                                 debug_affine_csv.size)) {
            console_line(2, "decode: failed to reset affine CSV");
            return 1;
        }
    }
    bitstream.release();
    bit_count = 0u;
    aggregate_state = PpmParserState();
    have_metadata = false;
    if (file_count == 0u) {
        makocode::ByteBuffer ppm_stream;
        if (!read_entire_stdin(ppm_stream)) {
            console_line(2, "decode: failed to read stdin");
            return 1;
        }

        makocode::ByteBuffer frame_bits;
        makocode::ByteBuffer frame_erasure_bits;
        u64 frame_bit_count = 0u;
        PpmParserState single_state;
        bool retry_without_subgrid_allowed = false;
        bool single_color_rotation = false;
        bool frame_extracted = ppm_extract_frame_bits(ppm_stream,
                                                      mapping,
                                                      frame_bits,
                                                      frame_bit_count,
                                                      single_state,
                                                      force_disable_subgrid,
                                                      &retry_without_subgrid_allowed,
                                                      debug_requested ? &debug_fiducial_csv : (makocode::ByteBuffer*)0,
                                                      1u,
                                                      &frame_erasure_bits,
                                                      &overlay_selector_seed,
                                                      &overlay_selector_counts,
                                                      &overlay_unknown_parity_budget,
                                                      &overlay_erasure_budget,
                                                      &single_color_rotation,
                                                      (const AffineTransform*)0,
                                                      force_tile_center_sampling,
                                                      0,
                                                      single_retry_tile_available
                                                          ? &single_retry_tile
                                                          : (const MetadataTile::Values*)0,
                                                      (const u8*)0,
                                                      0u,
                                                      0u,
                                                      small_scan_geometry_variant);

        if (!frame_extracted) {
            if (retry_without_subgrid_allowed && !force_disable_subgrid && !retried_subgrid) {

                console_line(2, "decode: retrying without fiducial subgrid (frame extraction failed)");
                force_disable_subgrid = true;
                retried_subgrid = true;
                goto retry_decode;
            }
            console_line(2, "decode: invalid ppm input");
            return 1;
        }
        if (debug_requested &&
            !append_affine_csv_row(debug_affine_csv, 1u, single_state.has_affine_transform,
                                   single_state.affine_transform.a00, single_state.affine_transform.a01,
                                   single_state.affine_transform.a10, single_state.affine_transform.a11,
                                   single_state.affine_transform.tx, single_state.affine_transform.ty)) {
            console_line(2, "decode: failed to append affine CSV");
            return 1;
        }
        if (debug_requested &&
            !write_bytes_to_file((const char*)debug_affine_path.data,
                                 debug_affine_csv.data,
                                 debug_affine_csv.size)) {
            console_line(2, "decode: failed to write affine CSV");
            return 1;
        }
        if (debug_requested &&
            !write_bytes_to_file((const char*)debug_fiducial_path.data,
                                 debug_fiducial_csv.data,
                                 debug_fiducial_csv.size)) {
            console_line(2, "decode: failed to write fiducial CSV");
            return 1;
        }
        if (single_color_rotation) {
            for (usize i = 0u; i < frame_bits.size; ++i) {
                u8 rotate = (u8)((i % 3u) + 1u);
                frame_bits.data[i] = rotate_right_u8(frame_bits.data[i], rotate);
            }
            for (usize i = 0u; i < frame_erasure_bits.size; ++i) {
                u8 rotate = (u8)((i % 3u) + 1u);
                frame_erasure_bits.data[i] = rotate_right_u8(frame_erasure_bits.data[i], rotate);
            }
        }
        bool payload_extracted = frame_bits_to_payload(frame_bits.data,
                                                       frame_bit_count,
                                                       single_state,
                                                       bitstream,
                                                       bit_count,
                                                       &encoded_frame_bits,
                                                       frame_erasure_bits.data,
                                                       frame_bit_count,
                                                       &erased_payload_symbols);

        encoded_page_present[0] = single_state.has_encoded_tile;
        encoded_pages[0] = single_state.encoded_tile;
        encoded_page_count = 1u;
        if (single_state.has_encoded_tile) {
            single_retry_tile = single_state.encoded_tile;
            single_retry_tile_available = true;
        }

        if (!payload_extracted) {
            if (!force_disable_subgrid && !retried_subgrid) {

                console_line(2, "decode: retrying without fiducial subgrid (payload header unreadable)");
                force_disable_subgrid = true;
                retried_subgrid = true;
                goto retry_decode;
            }
            console_line(2, "decode: failed to extract payload bits");
            return 1;
        }
        if (single_state.has_ecc_flag && !single_state.ecc_flag_value) {
            byte_buffer_move(frame_bits_for_length_recovery, frame_bits);
            frame_bit_count_for_length_recovery = frame_bit_count;
        }
        aggregate_state = single_state;
        have_metadata = true;

    } else {
        makocode::BitWriter frame_aggregator;
        makocode::BitWriter erasure_aggregator;
        frame_aggregator.reset();
        erasure_aggregator.reset();
        bool aggregate_initialized = false;
        bool first_page_has_selector_tile = false;
        bool have_first_page_selector_tile = false;
        bool aggregate_color_rotation = false;
        bool have_aggregate_color_rotation = false;
        MetadataTile::Values first_page_selector_tile;
        u64 expected_page_index = 1u;
        AffineTransform previous_page_affine_hint = {};
        bool previous_page_affine_hint_available = false;
        for (usize file_index = 0u; file_index < file_count; ++file_index) {
            makocode::ByteBuffer ppm_stream;
            if (!read_entire_file(input_files[file_index], ppm_stream)) {
                console_write(2, "decode: failed to read ");
                console_line(2, input_files[file_index]);
                return 1;
            }

            
            
            makocode::ByteBuffer page_bits;
            makocode::ByteBuffer page_erasure_bits;
            makocode::ByteBuffer page_overlay_selector_counts;
            u64 page_overlay_selector_seed = 0u;
            u64 page_bit_count = 0u;
            u64 page_capacity_bits = 0u;
            PpmParserState page_state;
            u16 page_unknown_parity_budget = 0u;
            u16 page_overlay_erasure_budget = 0u;
            bool page_color_rotation = false;
            bool retry_without_subgrid_allowed = false;
            bool frame_extracted = ppm_extract_frame_bits(ppm_stream,
                                                          mapping,
                                                          page_bits,
                                                          page_bit_count,
                                                          page_state,
                                                          force_disable_subgrid,
                                                          &retry_without_subgrid_allowed,
                                                          debug_requested ? &debug_fiducial_csv : (makocode::ByteBuffer*)0,
                                                          (u64)file_index + 1u,
                                                          &page_erasure_bits,
                                                          &page_overlay_selector_seed,
                                                          &page_overlay_selector_counts,
                                                          &page_unknown_parity_budget,
                                                          &page_overlay_erasure_budget,
                                                          &page_color_rotation,
                                                          previous_page_affine_hint_available
                                                              ? &previous_page_affine_hint
                                                              : (const AffineTransform*)0,
                                                          force_tile_center_sampling,
                                                          &page_capacity_bits,
                                                          file_count == 1u && single_retry_tile_available
                                                              ? &single_retry_tile
                                                              : (const MetadataTile::Values*)0,
                                                          (const u8*)0,
                                                          0u,
                                                          0u,
                                                          small_scan_geometry_variant);

            if (!frame_extracted) {
                if (retry_without_subgrid_allowed && !force_disable_subgrid && !retried_subgrid) {

                    console_line(2, "decode: retrying without fiducial subgrid (frame extraction failed)");
                    force_disable_subgrid = true;
                    retried_subgrid = true;
                    goto retry_decode;
                }
                console_write(2, "decode: invalid ppm in ");
                console_line(2, input_files[file_index]);
                return 1;
            }
            if (page_state.affine_fit_covers_page && page_state.has_affine_transform) {
                previous_page_affine_hint = page_state.affine_transform;
                previous_page_affine_hint_available = true;
            }
            if (!have_aggregate_color_rotation) {
                aggregate_color_rotation = page_color_rotation;
                have_aggregate_color_rotation = true;
            } else if (aggregate_color_rotation != page_color_rotation) {
                console_line(2, "decode: conflicting color rotation settings between pages");
                return 1;
            }
            bool page_has_selector_tile = page_state.has_encoded_tile &&
                metadata_schema_is_at_least(page_state.encoded_tile.schema_version, 2u) &&
                page_state.encoded_tile.overwrite_layout;
            if (!have_first_page_selector_tile) {
                have_first_page_selector_tile = true;
                first_page_has_selector_tile = page_has_selector_tile;
                if (page_has_selector_tile) {
                    first_page_selector_tile = page_state.encoded_tile;
                }
            } else if (page_has_selector_tile != first_page_has_selector_tile) {
                console_line(2, "decode: conflicting overlay selector settings between pages");
                return 1;
            }
            if (page_has_selector_tile &&
                (page_state.encoded_tile.overlay_selector_present !=
                     first_page_selector_tile.overlay_selector_present ||
                 page_state.encoded_tile.overlay_selector_seed !=
                     first_page_selector_tile.overlay_selector_seed ||
                 page_state.encoded_tile.unknown_parity_budget !=
                     first_page_selector_tile.unknown_parity_budget ||
                 page_state.encoded_tile.overlay_erasure_budget !=
                     first_page_selector_tile.overlay_erasure_budget ||
                 page_state.encoded_tile.ecc_enabled != first_page_selector_tile.ecc_enabled ||
                 page_state.encoded_tile.ecc_block_data != first_page_selector_tile.ecc_block_data ||
                 page_state.encoded_tile.ecc_parity != first_page_selector_tile.ecc_parity ||
                 page_state.encoded_tile.ecc_block_count != first_page_selector_tile.ecc_block_count ||
                 page_state.encoded_tile.ecc_original_bytes != first_page_selector_tile.ecc_original_bytes ||
                 page_state.encoded_tile.lzma_uncompressed_bytes !=
                     first_page_selector_tile.lzma_uncompressed_bytes)) {
                console_line(2, "decode: conflicting overlay selector settings between pages");
                return 1;
            }
            if (page_overlay_selector_counts.size) {
                if (!overlay_selector_counts.size) {
                    overlay_selector_seed = page_overlay_selector_seed;
                    overlay_unknown_parity_budget = page_unknown_parity_budget;
                    overlay_erasure_budget = page_overlay_erasure_budget;
                    if (!overlay_selector_counts.ensure(page_overlay_selector_counts.size)) {
                        console_line(2, "decode: failed to allocate overlay selector map");
                        return 1;
                    }
                    overlay_selector_counts.size = page_overlay_selector_counts.size;
                    for (usize i = 0u; i < overlay_selector_counts.size; ++i) {
                        overlay_selector_counts.data[i] = page_overlay_selector_counts.data[i];
                    }
                } else {
                    if (overlay_selector_seed != page_overlay_selector_seed ||
                        overlay_unknown_parity_budget != page_unknown_parity_budget ||
                        overlay_erasure_budget != page_overlay_erasure_budget ||
                        overlay_selector_counts.size != page_overlay_selector_counts.size) {
                        console_line(2, "decode: conflicting overlay selector settings between pages");
                        return 1;
                    }
                    for (usize i = 0u; i < overlay_selector_counts.size; ++i) {
                        if (page_overlay_selector_counts.data[i] > overlay_selector_counts.data[i]) {
                            overlay_selector_counts.data[i] = page_overlay_selector_counts.data[i];
                        }
                    }
                }
            }
            if (debug_requested &&
                !append_affine_csv_row(debug_affine_csv, (u64)file_index + 1u,
                                       page_state.has_affine_transform,
                                       page_state.affine_transform.a00, page_state.affine_transform.a01,
                                       page_state.affine_transform.a10, page_state.affine_transform.a11,
                                       page_state.affine_transform.tx, page_state.affine_transform.ty)) {
                console_line(2, "decode: failed to append affine CSV");
                return 1;
            }
            if (debug_requested &&
                !write_bytes_to_file((const char*)debug_affine_path.data,
                                     debug_affine_csv.data,
                                     debug_affine_csv.size)) {
                console_line(2, "decode: failed to write affine CSV");
                return 1;
            }
            if (debug_requested &&
                !write_bytes_to_file((const char*)debug_fiducial_path.data,
                                     debug_fiducial_csv.data,
                                     debug_fiducial_csv.size)) {
                console_line(2, "decode: failed to write fiducial CSV");
                return 1;
            }
            if (!aggregate_initialized) {
                merge_parser_state(aggregate_state, page_state);
                aggregate_initialized = true;
            } else {
                if (!merge_parser_state(aggregate_state, page_state)) {
                    console_line(2, "decode: conflicting metadata between pages");
                    return 1;
                }
            }
            encoded_page_present[encoded_page_count] = page_state.has_encoded_tile;
            encoded_pages[encoded_page_count++] = page_state.encoded_tile;
            if (!page_state.has_page_index || page_state.page_index_value == 0u) {
                page_state.has_page_index = true;
                page_state.page_index_value = expected_page_index;
            }
            if (page_state.page_index_value != expected_page_index) {
                char expected_buffer[32];
                char actual_buffer[32];
                u64_to_ascii(expected_page_index, expected_buffer, sizeof(expected_buffer));
                u64_to_ascii(page_state.page_index_value, actual_buffer, sizeof(actual_buffer));
                console_write(2, "decode: unexpected page order (expected: ");
                console_write(2, expected_buffer);
                console_write(2, ", actual: ");
                console_write(2, actual_buffer);
                console_line(2, ")");
                return 1;
            }
            u64 effective_bits = page_bit_count;
            bool canonical_exact_frame_length =
                page_state.has_encoded_tile &&
                metadata_schema_is_at_least(page_state.encoded_tile.schema_version, 2u) &&
                page_state.encoded_tile.overwrite_layout &&
                page_state.has_page_bits;
            if (canonical_exact_frame_length) {
                u64 page_number = page_state.has_page_index && page_state.page_index_value > 0u
                                      ? page_state.page_index_value
                                      : expected_page_index;
                u64 page_offset = 0u;
                if (page_capacity_bits == 0u ||
                    (page_number > 1u &&
                     page_capacity_bits > U64_MAX_VALUE / (page_number - 1u))) {
                    console_line(2, "decode: page frame offset overflow");
                    return 1;
                }
                page_offset = (page_number - 1u) * page_capacity_bits;
                if (page_offset >= page_state.page_bits_value) {
                    effective_bits = 0u;
                } else {
                    u64 remaining_bits = page_state.page_bits_value - page_offset;
                    if (remaining_bits < effective_bits) effective_bits = remaining_bits;
                }
            } else if (page_state.has_page_bits &&
                       page_state.page_bits_value <= effective_bits) {
                effective_bits = page_state.page_bits_value;
            }
            if (!append_bits_from_buffer(frame_aggregator, page_bits.data, effective_bits)) {
                console_line(2, "decode: failed to assemble bitstream");
                return 1;
            }
            if (page_erasure_bits.data && page_erasure_bits.size) {
                if (!append_bits_from_buffer(erasure_aggregator,
                                             page_erasure_bits.data,
                                             effective_bits)) {
                    console_line(2, "decode: failed to assemble erasure map");
                    return 1;
                }
            } else {
                for (u64 bit_index = 0u; bit_index < effective_bits; ++bit_index) {
                    if (!erasure_aggregator.write_bit(0u)) {
                        console_line(2, "decode: failed to assemble erasure map");
                        return 1;
                    }
                }
            }
            ++expected_page_index;
        }
        u64 frame_bit_total = frame_aggregator.bit_size();
        if (aggregate_color_rotation) {
            usize frame_bytes = frame_aggregator.byte_size();
            for (usize i = 0u; i < frame_bytes; ++i) {
                u8 rotate = (u8)((i % 3u) + 1u);
                frame_aggregator.buffer.data[i] =
                    rotate_right_u8(frame_aggregator.buffer.data[i], rotate);
            }
            usize erasure_bytes = erasure_aggregator.byte_size();
            for (usize i = 0u; i < erasure_bytes; ++i) {
                u8 rotate = (u8)((i % 3u) + 1u);
                erasure_aggregator.buffer.data[i] =
                    rotate_right_u8(erasure_aggregator.buffer.data[i], rotate);
            }
        }
        const u8* frame_data = frame_aggregator.data();
        bool payload_extracted = frame_bits_to_payload(frame_data,
                                                       frame_bit_total,
                                                       aggregate_state,
                                                       bitstream,
                                                       bit_count,
                                                       &encoded_frame_bits,
                                                       erasure_aggregator.data(),
                                                       frame_bit_total,
                                                       &erased_payload_symbols);

        if (!payload_extracted) {
            if (!force_disable_subgrid && !retried_subgrid) {

                console_line(2, "decode: retrying without fiducial subgrid (payload header unreadable)");
                force_disable_subgrid = true;
                retried_subgrid = true;
                goto retry_decode;
            }
            console_line(2, "decode: failed to extract payload bits");
            return 1;
        }
        if (aggregate_state.has_ecc_flag && !aggregate_state.ecc_flag_value) {
            byte_buffer_move(frame_bits_for_length_recovery, frame_aggregator.buffer);
            frame_bit_count_for_length_recovery = frame_bit_total;
        }
        have_metadata = true;

    }
    if (have_metadata &&
        aggregate_state.has_palette_text &&
        aggregate_state.palette_text_length &&
        !mapping.palette_set) {
        image_mapping_set_palette_text(mapping,
                                       aggregate_state.palette_text,
                                       aggregate_state.palette_text_length,
                                       "decode");
        if (!image_mapping_build_custom_palette(mapping, "decode")) {
            return 1;
        }
    }
    bool metadata_v2_layout = aggregate_state.has_encoded_tile &&
                              metadata_schema_is_at_least(aggregate_state.encoded_tile.schema_version, 2u);
    bool ecc_header_repaired = false;
    makocode::EccHeaderInfo bitstream_header;
    bool bitstream_header_present = false;
    bool bitstream_header_valid = false;
    if (!metadata_v2_layout && bitstream.data &&
        bitstream.size >= makocode::ECC_HEADER_TOTAL_BYTES) {
        bitstream_header_present = makocode::parse_ecc_header(bitstream.data, bitstream.size, bitstream_header);
        bitstream_header_valid = bitstream_header_present && bitstream_header.valid && bitstream_header.enabled;
    }
    bool ecc_metadata_available = have_metadata &&
                                  aggregate_state.has_ecc_flag &&
                                  aggregate_state.ecc_flag_value;
    bool ecc_metadata_complete = ecc_metadata_available &&
                                 aggregate_state.has_ecc_block_data &&
                                 aggregate_state.has_ecc_parity &&
                                 aggregate_state.has_ecc_block_count &&
                                 aggregate_state.has_ecc_original_bytes;
    
    if (!metadata_v2_layout && !bitstream_header_valid) {
        if (ecc_metadata_complete &&
            bitstream.data &&
            bitstream.size >= makocode::ECC_HEADER_TOTAL_BYTES &&
            bit_count >= (u64)makocode::ECC_HEADER_TOTAL_BITS) {
            u64 block_data_value = aggregate_state.ecc_block_data_value;
            u64 parity_value = aggregate_state.ecc_parity_value;
            if (block_data_value <= 0xFFFFu && parity_value <= 0xFFFFu) {
                u8 header_bytes[makocode::ECC_HEADER_TOTAL_BYTES];
                if (makocode::build_ecc_header_bytes(header_bytes,
                                                     (u16)block_data_value,
                                                     (u16)parity_value,
                                                     aggregate_state.ecc_block_count_value,
                                                     aggregate_state.ecc_original_bytes_value,
                                                     aggregate_state.has_encoded_tile
                                                         ? aggregate_state.encoded_tile.ecc_header_magic
                                                         : makocode::ECC_HEADER_MAGIC,
                                                     aggregate_state.has_encoded_tile
                                                         ? aggregate_state.encoded_tile.ecc_header_version
                                                         : makocode::ECC_HEADER_VERSION,
                                                     aggregate_state.has_encoded_tile
                                                         ? aggregate_state.encoded_tile.ecc_header_flags
                                                         : 0x01u,
                                                     aggregate_state.has_encoded_tile
                                                         ? aggregate_state.encoded_tile.ecc_header_reserved
                                                         : 0u)) {
                    bool differs = false;
                    for (usize i = 0u; i < makocode::ECC_HEADER_TOTAL_BYTES; ++i) {
                        if (bitstream.data[i] != header_bytes[i]) {
                            differs = true;
                            break;
                        }
                    }
                    if (differs) {
                        for (usize i = 0u; i < makocode::ECC_HEADER_TOTAL_BYTES; ++i) {
                            bitstream.data[i] = header_bytes[i];
                        }
                        ecc_header_repaired = true;
                    }
                }
            }
        } else if (ecc_metadata_available) {
            
            console_line(2, "decode: warning: ECC metadata incomplete; header reconstruction skipped");
        }
    }
    if (ecc_header_repaired) {
        console_line(2, "decode: repaired ECC header from metadata");
    }
    makocode::ByteBuffer synthetic_header_stream;
    makocode::ByteBuffer synthetic_header_erasures;
    const u8* decoder_stream_data = bitstream.data;
    u64 decoder_stream_bits = bit_count;
    const u8* decoder_erasure_data = erased_payload_symbols.data;
    usize decoder_erasure_bytes = erased_payload_symbols.size;
    bool synthetic_ecc_header = false;
    if (metadata_v2_layout && ecc_metadata_complete) {
        if (!bitstream.data || (bit_count & 7u) != 0u ||
            bit_count > U64_MAX_VALUE - (u64)makocode::ECC_HEADER_TOTAL_BITS ||
            bitstream.size > USIZE_MAX_VALUE - makocode::ECC_HEADER_TOTAL_BYTES ||
            aggregate_state.ecc_block_data_value > 0xFFFFu ||
            aggregate_state.ecc_parity_value > 0xFFFFu ||
            !synthetic_header_stream.ensure(bitstream.size + makocode::ECC_HEADER_TOTAL_BYTES)) {
            console_line(2, "decode: invalid metadata ECC header");
            return 1;
        }
        u8 header_bytes[makocode::ECC_HEADER_TOTAL_BYTES];
        if (!makocode::build_ecc_header_bytes(header_bytes,
                                              (u16)aggregate_state.ecc_block_data_value,
                                              (u16)aggregate_state.ecc_parity_value,
                                              aggregate_state.ecc_block_count_value,
                                              aggregate_state.ecc_original_bytes_value,
                                              aggregate_state.encoded_tile.ecc_header_magic,
                                              aggregate_state.encoded_tile.ecc_header_version,
                                              aggregate_state.encoded_tile.ecc_header_flags,
                                              aggregate_state.encoded_tile.ecc_header_reserved)) {
            console_line(2, "decode: invalid metadata ECC header");
            return 1;
        }
        synthetic_header_stream.size = makocode::ECC_HEADER_TOTAL_BYTES + bitstream.size;
        for (usize i = 0u; i < makocode::ECC_HEADER_TOTAL_BYTES; ++i) {
            synthetic_header_stream.data[i] = header_bytes[i];
        }
        for (usize i = 0u; i < bitstream.size; ++i) {
            synthetic_header_stream.data[makocode::ECC_HEADER_TOTAL_BYTES + i] = bitstream.data[i];
        }
        decoder_stream_data = synthetic_header_stream.data;
        decoder_stream_bits = bit_count + (u64)makocode::ECC_HEADER_TOTAL_BITS;
        synthetic_ecc_header = true;
        if (erased_payload_symbols.data) {
            if (erased_payload_symbols.size < bitstream.size ||
                !synthetic_header_erasures.ensure(synthetic_header_stream.size)) {
                console_line(2, "decode: invalid payload erasure map");
                return 1;
            }
            synthetic_header_erasures.size = synthetic_header_stream.size;
            for (usize i = 0u; i < makocode::ECC_HEADER_TOTAL_BYTES; ++i) {
                synthetic_header_erasures.data[i] = 0u;
            }
            for (usize i = 0u; i < bitstream.size; ++i) {
                synthetic_header_erasures.data[makocode::ECC_HEADER_TOTAL_BYTES + i] =
                    erased_payload_symbols.data[i];
            }
            decoder_erasure_data = synthetic_header_erasures.data;
            decoder_erasure_bytes = synthetic_header_erasures.size;
        }
    }
    makocode::DecoderContext decoder;
    const char* password_ptr = have_password ? (const char*)password_buffer.data : (const char*)0;
    usize password_length = have_password ? password_buffer.size : 0u;
    if (!decoder.parse((u8*)decoder_stream_data,
                       decoder_stream_bits,
                       password_ptr,
                       password_length,
                       decoder_erasure_data,
                       decoder_erasure_bytes,
                       overlay_selector_seed,
                       overlay_selector_counts.data,
                       overlay_selector_counts.size,
                       overlay_unknown_parity_budget,
                       overlay_erasure_budget,
                       metadata_v2_layout,
                       synthetic_ecc_header,
                       aggregate_state.has_encoded_tile &&
                               metadata_schema_is_at_least(aggregate_state.encoded_tile.schema_version, 3u)
                           ? aggregate_state.encoded_tile.lzma_uncompressed_bytes
                           : makocode::LZMA_SIZE_FROM_HEADER,
                       !(aggregate_state.has_encoded_tile &&
                         metadata_schema_is_at_least(aggregate_state.encoded_tile.schema_version, 4u)))) {
        if (decoder.password_auth_failed()) {
            console_line(2, "decode: decryption failed (password mismatch or corrupted data)");
            return 1;
        }
        bool frame_length_recovered = false;
        if (!decoder.ecc_correction_failed() &&
            !have_password &&
            !metadata_v2_layout &&
            aggregate_state.has_ecc_flag &&
            !aggregate_state.ecc_flag_value &&
            frame_bits_for_length_recovery.data &&
            frame_bit_count_for_length_recovery > 64u) {
            makocode::BitReader length_reader;
            length_reader.reset(frame_bits_for_length_recovery.data,
                                frame_bit_count_for_length_recovery);
            u64 observed_bits = length_reader.read_bits(64u);
            u64 available_bits = frame_bit_count_for_length_recovery - 64u;
            makocode::ByteBuffer recovered_stream;
            u64 recovered_bits = 0u;
            u32 valid_candidates = 0u;
            for (u32 header_bit = 0u; header_bit < 64u; ++header_bit) {
                u64 candidate_bits = observed_bits ^ (1ull << header_bit);
                if (candidate_bits == 0u ||
                    (candidate_bits & 7u) != 0u ||
                    candidate_bits > available_bits) {
                    continue;
                }
                u8& candidate_header_byte =
                    frame_bits_for_length_recovery.data[header_bit >> 3u];
                candidate_header_byte ^= (u8)(1u << (header_bit & 7u));
                makocode::ByteBuffer candidate_stream;
                u64 candidate_stream_bits = 0u;
                bool candidate_extracted = frame_bits_to_payload(
                    frame_bits_for_length_recovery.data,
                    frame_bit_count_for_length_recovery,
                    aggregate_state,
                    candidate_stream,
                    candidate_stream_bits);
                candidate_header_byte ^= (u8)(1u << (header_bit & 7u));
                if (!candidate_extracted || candidate_stream_bits != candidate_bits) {
                    continue;
                }
                makocode::ByteBuffer candidate_input;
                if (!candidate_input.ensure(candidate_stream.size)) {
                    continue;
                }
                candidate_input.size = candidate_stream.size;
                for (usize i = 0u; i < candidate_stream.size; ++i) {
                    candidate_input.data[i] = candidate_stream.data[i];
                }
                makocode::DecoderContext candidate_decoder;
                if (!candidate_decoder.parse(candidate_input.data,
                                             candidate_stream_bits,
                                             (const char*)0,
                                             0u)) {
                    continue;
                }
                const makocode::ByteBuffer& archive = candidate_decoder.payload;
                bool archive_valid = archive_is_well_formed(archive);
                if (archive_valid) {
                    ++valid_candidates;
                    if (valid_candidates == 1u) {
                        byte_buffer_move(recovered_stream, candidate_stream);
                        recovered_bits = candidate_stream_bits;
                    }
                }
            }
            if (valid_candidates == 1u) {
                byte_buffer_move(bitstream, recovered_stream);
                bit_count = recovered_bits;
                frame_length_recovered = decoder.parse(bitstream.data,
                                                       bit_count,
                                                       password_ptr,
                                                       password_length);
                if (frame_length_recovered) {
                    console_line(2, "decode: recovered frame length from a one-bit header correction");
                }
            }
        }
        if (!frame_length_recovered) {
            if (!decoder.ecc_correction_failed() && !force_disable_subgrid && !retried_subgrid) {
                console_line(2, "decode: parse failure; retrying without fiducial subgrid");
                force_disable_subgrid = true;
                retried_subgrid = true;
                goto retry_decode;
            }
            if (decoder.ecc_correction_failed() && !force_disable_subgrid && !retried_subgrid) {
                console_line(2, "decode: ECC could not repair the payload; retrying without fiducial subgrid");
                if (file_count == 1u && aggregate_state.has_encoded_tile &&
                    aggregate_state.encoded_tile.page_width_pixels > 96u &&
                    aggregate_state.encoded_tile.page_height_pixels > 96u) {
                    single_retry_tile = aggregate_state.encoded_tile;
                    single_retry_tile_available = true;
                }
                force_disable_subgrid = true;
                retried_subgrid = true;
                goto retry_decode;
            }
            if (decoder.ecc_correction_failed() && !force_tile_center_sampling &&
                aggregate_state.has_encoded_tile &&
                aggregate_state.encoded_tile.page_width_pixels <= 96u &&
                aggregate_state.encoded_tile.page_height_pixels <= 96u) {
                force_tile_center_sampling = true;
                force_disable_subgrid = true;
                retried_subgrid = true;
                goto retry_decode;
            }
            if (decoder.ecc_correction_failed() && force_tile_center_sampling &&
                aggregate_state.has_encoded_tile &&
                aggregate_state.encoded_tile.palette_count == 2u &&
                aggregate_state.encoded_tile.page_width_pixels <= 96u &&
                aggregate_state.encoded_tile.page_height_pixels <= 96u &&
                small_scan_geometry_variant < 10u) {
                ++small_scan_geometry_variant;
                console_line(2, "decode: ECC could not repair payload; retrying adjacent small-scan geometry");
                goto retry_decode;
            }
            if (decoder.ecc_correction_failed()) {
                console_line(2, "decode: ECC could not repair the payload");
            } else {
                console_line(2, "decode: parse failure");
            }
            return 1;
        }
    }
    frame_bits_for_length_recovery.release();
    if (decoder.password_attempt_made() && decoder.password_was_ignored()) {
        console_line(2, "decode: warning: payload was not encrypted; password ignored");
    }
    const makocode::EccDecodeStats& ecc_stats = decoder.ecc_statistics();
    if (ecc_stats.total_parity_symbols > 0u) {
        u64 corrected_bits = ecc_stats.corrected_symbols * 8u;
        u64 available_bits = ecc_stats.total_parity_symbols * 8u;
        double usage = 0.0;
        if (available_bits > 0u) {
            usage = ((double)corrected_bits * 100.0) / (double)available_bits;
        }
        char count_buffer[32];
        char bits_buffer[32];
        char percent_buffer[32];
        u64_to_ascii(ecc_stats.corrected_symbols, count_buffer, sizeof(count_buffer));
        u64_to_ascii(corrected_bits, bits_buffer, sizeof(bits_buffer));
        format_fixed_3(usage, percent_buffer, sizeof(percent_buffer));
        int ecc_output = decoded_stdout_requested ? 2 : 1;
        console_write(ecc_output, "decode: ECC detected ");
        console_write(ecc_output, count_buffer);
        console_write(ecc_output, (ecc_stats.corrected_symbols == 1u) ? " symbol error (" : " symbol errors (");
        console_write(ecc_output, bits_buffer);
        console_write(ecc_output, (corrected_bits == 1u) ? " bit corrected, " : " bits corrected, ");
        console_write(ecc_output, percent_buffer);
        console_line(ecc_output, "% of available correction bits)");
    }
    if (decoded_file_requested || decoded_stdout_requested) {
        const makocode::ByteBuffer& archive = decoder.payload;
        makocode::ByteBuffer decoded;
        bool ok = decoded.append_ascii("MAKOCODE-DECODED\n");
        char number[32];
        for (usize page = 0; ok && page < encoded_page_count; ++page) {
            u64_to_ascii(page + 1u, number, sizeof(number));
            ok = decoded.append_ascii("page ") && decoded.append_ascii(number) && decoded.append_char('\n');
            if (encoded_page_present[page]) {
                const MetadataTile::Values& tile = encoded_pages[page];
                const char* names[] = {"tile_schema", "page_bits", "page_count", "page_index", "width", "height", "footer_rows", "fiducial_size", "ecc_enabled", "ecc_block_data", "ecc_parity", "ecc_block_count", "ecc_original_bytes", "palette_count"};
                u64 values[] = {MetadataTile::TILE_SCHEMA_VERSION, tile.page_bits, tile.page_count, tile.page_index, tile.page_width_pixels, tile.page_height_pixels, tile.footer_rows, tile.fiducial_marker_size_pixels, tile.ecc_enabled ? 1u : 0u, tile.ecc_block_data, tile.ecc_parity, tile.ecc_block_count, tile.ecc_original_bytes, tile.palette_count};
                for (usize i = 0; ok && i < sizeof(values) / sizeof(values[0]); ++i) {
                    u64_to_ascii(values[i], number, sizeof(number));
                    ok = decoded.append_ascii("metadata ") && decoded.append_ascii(names[i]) && decoded.append_char(' ') && decoded.append_ascii(number) && decoded.append_char('\n');
                }
                for (u32 i = 0; ok && i < tile.palette_count; ++i) {
                    static const char hex[] = "0123456789ABCDEF";
                    const u8 rgb[] = {tile.palette[i].r, tile.palette[i].g, tile.palette[i].b};
                    ok = decoded.append_ascii("metadata palette ");
                    for (usize j = 0; ok && j < 3u; ++j) {
                        ok = decoded.append_char(hex[rgb[j] >> 4u]) && decoded.append_char(hex[rgb[j] & 15u]);
                    }
                    ok = ok && decoded.append_char('\n');
                }
            }
            ok = ok && decoded.append_ascii("end-page\n");
        }
        ok = ok && decoded.append_ascii("payload\n");
        u64 reported_frame_bits = (encoded_frame_bits == bit_count)
                                      ? encoded_frame_bits
                                      : (aggregate_state.has_page_bits
                                             ? aggregate_state.page_bits_value
                                             : ((encoded_page_count > 0u &&
                                                 encoded_page_present[0u])
                                                    ? encoded_pages[0u].page_bits
                                                    : 0u));
        if (reported_frame_bits > 0u) {
            u64_to_ascii(reported_frame_bits, number, sizeof(number));
            ok = ok && decoded.append_ascii("metadata frame_bits ") && decoded.append_ascii(number) && decoded.append_char('\n');
        }
        const makocode::EncodedPayloadMetadata& payload_metadata = decoder.encoded_metadata;
        if (payload_metadata.ecc_present) {
            const makocode::EccHeader& ecc = payload_metadata.ecc;
            const char* names[] = {"ecc_magic", "ecc_version", "ecc_flags", "ecc_reserved", "ecc_block_data", "ecc_parity", "ecc_block_count", "ecc_original_bytes"};
            u64 values[] = {ecc.magic, ecc.version, ecc.flags, ecc.reserved, ecc.block_data, ecc.parity, ecc.block_count, ecc.original_bytes};
            for (usize i = 0; ok && i < sizeof(values) / sizeof(values[0]); ++i) {
                u64_to_ascii(values[i], number, sizeof(number));
                ok = decoded.append_ascii("metadata ") && decoded.append_ascii(names[i]) && decoded.append_char(' ') && decoded.append_ascii(number) && decoded.append_char('\n');
            }
        }
        if (payload_metadata.encryption_present) {
            const u8* header = payload_metadata.encryption_header;
            const char* names[] = {"encryption_magic", "encryption_version", "encryption_flags", "encryption_kdf", "encryption_reserved", "encryption_iterations", "encryption_plaintext_bytes"};
            u64 values[] = {read_le_u32(header), header[4], header[5], header[6], header[7], read_le_u32(header + 8u), read_le_u64(header + 12u)};
            for (usize i = 0; ok && i < sizeof(values) / sizeof(values[0]); ++i) {
                u64_to_ascii(values[i], number, sizeof(number));
                ok = decoded.append_ascii("metadata ") && decoded.append_ascii(names[i]) && decoded.append_char(' ') && decoded.append_ascii(number) && decoded.append_char('\n');
            }
            const char* byte_names[] = {"encryption_salt", "encryption_nonce", "encryption_tag"};
            const u8* bytes[] = {header + 20u, header + 36u, payload_metadata.encryption_tag};
            usize sizes[] = {16u, 12u, 16u};
            static const char digits[] = "0123456789ABCDEF";
            for (usize i = 0; ok && i < 3u; ++i) {
                ok = decoded.append_ascii("metadata ") && decoded.append_ascii(byte_names[i]) && decoded.append_char(' ');
                for (usize j = 0; ok && j < sizes[i]; ++j) ok = decoded.append_char(digits[bytes[i][j] >> 4u]) && decoded.append_char(digits[bytes[i][j] & 15u]);
                ok = ok && decoded.append_char('\n');
            }
        }
        if (payload_metadata.lzma_present) {
            u64_to_ascii(read_le_u64(payload_metadata.lzma_header + LZMA_PROPS_SIZE), number, sizeof(number));
            ok = decoded.append_ascii("metadata lzma_uncompressed_bytes ") && decoded.append_ascii(number) && decoded.append_char('\n');
        }
        struct ArchiveOutputContext {
            makocode::ByteBuffer* decoded;
            bool started;
        } archive_output = {&decoded, false};
        auto append_decoded_archive_entry = [](u8 type,
                                               const char* path,
                                               usize path_size,
                                               const u8* file_data,
                                               usize file_size,
                                               u64 entries,
                                               void* context) -> bool {
            ArchiveOutputContext* output = (ArchiveOutputContext*)context;
            makocode::ByteBuffer& target = *output->decoded;
            char number_buffer[32];
            static const char hex_digits[] = "0123456789ABCDEF";
            if (!output->started) {
                u64_to_ascii(entries, number_buffer, sizeof(number_buffer));
                if (!target.append_ascii("end-payload\narchive\nentries ") ||
                    !target.append_ascii(number_buffer) || !target.append_char('\n')) {
                    return false;
                }
                output->started = true;
            }
            if (!target.append_ascii(type == 1u ? "directory " : "file ")) return false;
            const u8* path_bytes = (const u8*)path;
            for (usize i = 0u; i < path_size; ++i) {
                u8 c = path_bytes[i];
                if (c >= 33u && c <= 126u && c != '\\') {
                    if (!target.append_char((char)c)) return false;
                } else if (!target.append_ascii("\\x") ||
                           !target.append_char(hex_digits[c >> 4u]) ||
                           !target.append_char(hex_digits[c & 15u])) {
                    return false;
                }
            }
            if (type == 0u) {
                u64_to_ascii((u64)file_size, number_buffer, sizeof(number_buffer));
                if (!target.append_char(' ') || !target.append_ascii(number_buffer) ||
                    !target.append_char('\n')) return false;
                for (usize i = 0u; i < file_size; ++i) {
                    u8 c = file_data[i];
                    if (c >= 32u && c <= 126u && c != '\\') {
                        if (!target.append_char((char)c)) return false;
                    } else if (!target.append_ascii("\\x") ||
                               !target.append_char(hex_digits[c >> 4u]) ||
                               !target.append_char(hex_digits[c & 15u])) {
                        return false;
                    }
                }
            }
            return target.append_char('\n');
        };
        ok = ok && archive.data && archive_parse(archive,
                                                  append_decoded_archive_entry,
                                                  &archive_output,
                                                  (u64*)0);
        ok = ok && archive_output.started && decoded.append_ascii("end-archive\nend\n");
        if (decoded_stdout_requested) {
            if (!ok || !write_all_fd(1, decoded.data, decoded.size)) {
                console_line(2, "decode: failed to write decoded stdout");
                return 1;
            }
            return 0;
        }
        time_t now = time(0);
        struct tm* local = localtime(&now);
        char filename[64];
        if (!local || !strftime(filename, sizeof(filename), "makocode_decoded_%Y%m%d%H%M%S.txt", local)) ok = false;
        makocode::ByteBuffer output_path;
        if (!ok || !join_output_path(output_dir, filename, output_path) ||
            !ensure_parent_directories((const char*)output_path.data)) {
            console_line(2, "decode: failed to write decoded file");
            return 1;
        }
        int output_fd = open((const char*)output_path.data, O_WRONLY | O_CREAT | O_EXCL, 0644);
        if (output_fd < 0) {
            console_line(2, "decode: failed to create decoded file");
            return 1;
        }
        bool written = write_all_fd(output_fd, decoded.data, decoded.size);
        if (close(output_fd) != 0) written = false;
        if (!written) {
            unlink((const char*)output_path.data);
            console_line(2, "decode: failed to write decoded file");
            return 1;
        }
        console_write(1, "decode: wrote ");
        console_line(1, (const char*)output_path.data);
        return 0;
    }
    if (!unpack_archive_to_directory(decoder.payload, output_dir)) {
        const char* raw_fallback = getenv("MAKOCODE_DECODE_RAW_FALLBACK");
        bool allow_raw_fallback = (raw_fallback && *raw_fallback && raw_fallback[0] != '0');
        if (allow_raw_fallback && output_dir) {
            // Fall back to emitting the raw payload (even if empty) only when explicitly enabled.
            char path_buffer[4096];
            usize dir_len = ascii_length(output_dir);
            const char* filename = "payload.bin";
            usize file_len = (usize)sizeof("payload.bin") - 1u;
            bool need_sep = (dir_len > 0u) && (output_dir[dir_len - 1u] != '/' && output_dir[dir_len - 1u] != '\\');
            usize total_len = dir_len + (need_sep ? 1u : 0u) + file_len;
            if (total_len < sizeof(path_buffer)) {
                usize cursor = 0u;
                for (usize i = 0u; i < dir_len; ++i) {
                    char c = output_dir[i];
                    if (c == '\\') {
                        c = '/';
                    }
                    path_buffer[cursor++] = c;
                }
                if (need_sep) {
                    path_buffer[cursor++] = '/';
                }
                for (usize i = 0u; i < file_len; ++i) {
                    path_buffer[cursor++] = filename[i];
                }
                path_buffer[cursor] = '\0';
                write_buffer_to_file(path_buffer, decoder.payload);
            }
            console_line(1, "decode: wrote raw payload.bin (MAKOCODE_DECODE_RAW_FALLBACK enabled)");
            return 0;
        }
        return 1;
    }
    console_write(1, "decode: wrote files to ");
    console_line(1, output_dir);
    return 0;
}

static bool read_file_into_buffer(const char* path, makocode::ByteBuffer& buffer) {
    buffer.release();
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        return false;
    }
    u8 chunk[4096];
    while (1) {
        int read_result = read(fd, chunk, sizeof(chunk));
        if (read_result < 0) {
            close(fd);
            buffer.release();
            return false;
        }
        if (read_result == 0) {
            break;
        }
        if (!buffer.append_bytes(chunk, (usize)read_result)) {
            close(fd);
            buffer.release();
            return false;
        }
    }
    close(fd);
    return true;
}

static bool strip_cpp_comments(const makocode::ByteBuffer& input,
                               makocode::ByteBuffer& output) {
    output.release();
    if (!input.data || input.size == 0u) {
        return true;
    }
    bool in_line_comment = false;
    bool in_block_comment = false;
    bool in_string = false;
    bool in_char = false;
    const u8* data = input.data;
    usize size = input.size;
    usize index = 0u;
    while (index < size) {
        u8 ch = data[index];
        if (in_line_comment) {
            if (ch == '\n' || ch == '\r') {
                if (!output.push(ch)) {
                    return false;
                }
                in_line_comment = false;
            }
            index += 1u;
            continue;
        }
        if (in_block_comment) {
            if (ch == '*' && (index + 1u) < size && data[index + 1u] == '/') {
                in_block_comment = false;
                index += 2u;
                continue;
            }
            if (ch == '\n' || ch == '\r') {
                if (!output.push(ch)) {
                    return false;
                }
            }
            index += 1u;
            continue;
        }
        if (in_string) {
            if (!output.push(ch)) {
                return false;
            }
            if (ch == '\\') {
                if ((index + 1u) < size) {
                    u8 next = data[index + 1u];
                    if (!output.push(next)) {
                        return false;
                    }
                    index += 2u;
                    continue;
                }
            } else if (ch == '"') {
                in_string = false;
            }
            index += 1u;
            continue;
        }
        if (in_char) {
            if (!output.push(ch)) {
                return false;
            }
            if (ch == '\\') {
                if ((index + 1u) < size) {
                    u8 next = data[index + 1u];
                    if (!output.push(next)) {
                        return false;
                    }
                    index += 2u;
                    continue;
                }
            } else if (ch == '\'') {
                in_char = false;
            }
            index += 1u;
            continue;
        }
        if (ch == '/' && (index + 1u) < size) {
            u8 next = data[index + 1u];
            if (next == '/') {
                in_line_comment = true;
                index += 2u;
                continue;
            }
            if (next == '*') {
                in_block_comment = true;
                index += 2u;
                continue;
            }
        }
        if (ch == '"') {
            in_string = true;
            if (!output.push(ch)) {
                return false;
            }
            index += 1u;
            continue;
        }
        if (ch == '\'') {
            in_char = true;
            if (!output.push(ch)) {
                return false;
            }
            index += 1u;
            continue;
        }
        if (!output.push(ch)) {
            return false;
        }
        index += 1u;
    }
    return true;
}

static int command_minify(int arg_count, char** args) {
    if (arguments_request_help(arg_count, args)) {
        write_minify_help();
        return 0;
    }
    (void)args;
    if (arg_count > 0) {
        console_line(2, "minify: this command does not accept arguments");
        return 1;
    }
    makocode::ByteBuffer source;
    if (!read_file_into_buffer("makocode.cpp", source)) {
        console_line(2, "minify: failed to read makocode.cpp");
        return 1;
    }
    makocode::ByteBuffer stripped;
    if (!strip_cpp_comments(source, stripped)) {
        console_line(2, "minify: failed to strip comments");
        return 1;
    }
    makocode::ByteBuffer minified;
    bool last_was_space = true;
    bool line_start = true;
    bool in_preprocessor = false;
    for (usize i = 0u; i < stripped.size; ++i) {
        u8 ch = stripped.data[i];
        if (ch == '\r') {
            ch = '\n';
        }
        if (ch == '\n') {
            if (in_preprocessor) {
                if (!minified.push('\n')) {
                    minified.release();
                    console_line(2, "minify: failed to compact whitespace");
                    return 1;
                }
                last_was_space = true;
            } else if (!last_was_space) {
                if (!minified.push(' ')) {
                    minified.release();
                    console_line(2, "minify: failed to compact whitespace");
                    return 1;
                }
                last_was_space = true;
            }
            line_start = true;
            in_preprocessor = false;
            continue;
        }
        bool is_space = (ch == ' ') || (ch == '\t') || (ch == '\f') || (ch == '\v');
        if (is_space) {
            if (line_start) {
                continue;
            }
            if (!last_was_space) {
                if (!minified.push(' ')) {
                    minified.release();
                    console_line(2, "minify: failed to compact whitespace");
                    return 1;
                }
                last_was_space = true;
            }
            continue;
        }
        if (line_start && ch == '#') {
            if (minified.size > 0u) {
                u8& previous = minified.data[minified.size - 1u];
                if (previous == ' ') {
                    previous = '\n';
                }
            }
            if (!minified.push('#')) {
                minified.release();
                console_line(2, "minify: failed to compact whitespace");
                return 1;
            }
            last_was_space = false;
            line_start = false;
            in_preprocessor = true;
            continue;
        }
        if (!minified.push(ch)) {
            minified.release();
            console_line(2, "minify: failed to compact whitespace");
            return 1;
        }
        last_was_space = false;
        line_start = false;
    }
    stripped.release();
    stripped.data = minified.data;
    stripped.size = minified.size;
    stripped.capacity = minified.capacity;
    minified.data = 0;
    minified.size = 0;
    minified.capacity = 0;
    usize end_index = stripped.size;
    while (end_index > 0u &&
           (stripped.data[end_index - 1u] == ' ' || stripped.data[end_index - 1u] == '\n')) {
        end_index -= 1u;
    }
    stripped.size = end_index;
    if (!write_bytes_to_file("makocode_minified.cpp", stripped.data, stripped.size)) {
        console_line(2, "minify: failed to write makocode_minified.cpp");
        return 1;
    }
    console_line(1, "minify: wrote makocode_minified.cpp");
    return 0;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        write_usage();
        return 0;
    }
    const char* command = argv[1];
    usize length = ascii_length(command);
    if (ascii_equals_token(command, length, "--help") ||
        ascii_equals_token(command, length, "-h")) {
        write_usage();
        return 0;
    }
    int command_argc = argc - 2;
    char** command_argv = argv + 2;
    if (ascii_compare(command, "encode") == 0) {
        return command_encode(command_argc, command_argv);
    }
    if (ascii_compare(command, "decode") == 0) {
        return command_decode(command_argc, command_argv);
    }
    if (ascii_compare(command, "overlay") == 0) {
        return command_overlay(command_argc, command_argv);
    }
    if (ascii_compare(command, "minify") == 0) {
        return command_minify(command_argc, command_argv);
    }
    write_usage();
    return 0;
}
